function normalizeTgChat(raw: string): string {
  let s = String(raw || '').trim();
  if (!s) return '';
  s = s.replace(/^(?:https?:\/\/)?(?:www\.)?t\.me\//i, '').replace(/^\/+/, '').trim();
  if (/^-?\d+$/.test(s)) return s;
  if (!s.startsWith('@')) s = '@' + s;
  return s;
}

