/* Принципиальные матчи — НЕ дерби. Учитываются в мотивации и подаче матча, но не помечаются как «дерби». */
const RIVALRIES = [
  ["Крылья Советов", "Акрон", "Битва Самары", "Принципиальное соперничество двух клубов из Самары, битва за звание лучшего клуба Самары"],
  ["Рубин", "Крылья Советов", "Волжское противостояние", "Противостояние двух клубов с берегов Волги — «Рубина» из Казани и «Крыльев Советов» из Самары — носит негласное название «Волжское дерби». Это один из самых принципиальных матчей для болельщиков обеих команд, который часто сравнивают с региональной версией противостояния «Спартак» — ЦСКА, настолько высоким бывает накал в этих встречах. История личных встреч насчитывает 56 матчей: 24 победы у «Рубина», 15 — у «Крыльев Советов» и 17 ничьих. Для болельщиков это самый принципиальный матч сезона, а на трибунах порой случались и стычки, и столкновения с полицией. В чемпионские времена Курбана Бердыева «Рубин» часто брал верх, но в последние годы «Крылья Советов» не проигрывают принципиальному сопернику в официальных матчах. С сезона-2024/25 очные встречи волжских клубов были объединены в неофициальный «Кубок Волги», что придало этому дерби дополнительный соревновательный смысл."],
  ["Ростов", "Краснодар", "Южное противостояние", "Это главная битва за юг России, и принципиальность здесь строится на географическом соседстве и борьбе за региональный престиж. Обе команды хотят быть лучшими на юге, поэтому матчи проходят с особым эмоциональным фоном. Игры всегда жаркие, с интригой и повышенной агрессией в борьбе — уступать принципиальному соседу никто не хочет."],
  ["Ахмат", "Динамо Махачкала", "Кавказское противостояние", "Это региональное кавказское дерби, принципиальность которого определяется борьбой за престиж региона и повышенной эмоциональностью. Для болельщиков обеих команд это не просто матч за очки, а вопрос уважения и статуса. Матчи всегда жаркие, с интригой и большим количеством единоборств — страсти здесь кипят и на поле, и на трибунах."],
];

function buildDerbyList(teamByName: (n: string) => any) {
  const out: any[] = [];
  for (const [a, b, name, note] of DERBIES) {
    if (teamByName(a) && teamByName(b)) out.push({ id: uid(), a: teamByName(a).id, b: teamByName(b).id, name, note, principled: false });
  }
  for (const [a, b, name, note] of RIVALRIES) {
    if (teamByName(a) && teamByName(b)) out.push({ id: uid(), a: teamByName(a).id, b: teamByName(b).id, name, note, principled: true });
  }
  return out;
}

function seed() {
  const d: any = {
    settings: {
      season: '2026/27',
      secPerMin: 4,
      breakSec: 20,
      chunks: 2,
      auto: false,
      squadMax: 28,
      grounding: false,
      tgToken: '',
      tgChat: '',
      siteUrl: '',
      systemPrompt: '',
      keys: {},
      models: {},
      adminCode: mkCode()
    },
    comps: COMPS,
    teams: [],
    players: [],
    squads: {},
    lineups: {},
    tactics: {},
    fixtures: [],
    derbies: [],
    transfers: [],
    sessions: {},
    llmlog: [],
    cup: null,
    budgetHistory: []
  };
  for (const [name, city, lat, lon, stadium] of RPL) {
    d.teams.push({ id: uid(), name, comp: 'rpl', city, lat, lon, stadium, code: mkCode(), logo: getTeamLogo(name, null, 'rpl') });
  }
  for (const [name, city, lat, lon, stadium] of FNL_TEAMS) {
    d.teams.push({ id: uid(), name, comp: 'fnl', city, lat, lon, stadium, code: mkCode(), logo: getTeamLogo(name, null, 'fnl') });
  }
  for (const c of Object.keys(LOWER)) {
    for (const name of LOWER[c]) {
      d.teams.push({ id: uid(), name, comp: c, city: '', lat: null, lon: null, stadium: '', code: '', logo: getTeamLogo(name, null, c) });
    }
  }
  const T = (n: string) => d.teams.find((t: any) => t.name === n);
  d.derbies = buildDerbyList(T);
  return d;
}

