/**
 * Вычисляет окно паузы на сборные по регламенту:
 * 1) 21 сентября — 6 октября (16 дней)
 * 2) 9–17 ноября (9 дней)
 * 3) 23–31 марта (9 дней)
 * 4) 1–9 июня (9 дней)
 *
 * Правило начала: пауза начинается с понедельника-вторника.
 * Если опорная дата выпадает на другой день (суббота, четверг, пятница, воскресенье, среда),
 * то клубы доигрывают матчи выходных, и сбор начинается в ближайший следующий понедельник.
 * Например:
 * - 9 ноября сб -> начало в пн, 11 ноября (+2 дня), длится 9 дней -> конец 19 ноября.
 * - 9 ноября чт -> начало в сл. пн, 13 ноября (+4 дня), длится 9 дней -> конец 21 ноября.
 * - если пн или вт -> начинается в этот день.
 * Длится ровно durationDays дней: end = addDays(start, durationDays - 1).
 */
function computeBreakWindow(baseDateStr: string, durationDays: number): { start: string; end: string } {
  const dow = new Date(baseDateStr + 'T12:00:00Z').getUTCDay(); // 0 = Sun, 1 = Mon, ..., 6 = Sat
  let start = baseDateStr;
  if (dow !== 1 && dow !== 2) {
    const shift = (8 - dow) % 7;
    start = addDays(baseDateStr, shift);
  }
  const end = addDays(start, durationDays - 1);
  return { start, end };
}

function getSeasonBreaks(startYear: number): any[] {
  const y = Number(startYear) || 2026;
  const sepOct = computeBreakWindow(`${y}-09-21`, 16);
  const nov = computeBreakWindow(`${y}-11-09`, 9);
  const winter = { start: `${y}-12-14`, end: `${y + 1}-02-27` };
  const mar = computeBreakWindow(`${y + 1}-03-23`, 9);
  const jun = computeBreakWindow(`${y + 1}-06-01`, 9);

  return [
    { id: 'ib_sepoct', name: 'Пауза на сборные (21 сентября — 6 октября, 16 дней)', start: sepOct.start, end: sepOct.end, duration: 16 },
    { id: 'ib_nov', name: 'Пауза на сборные (9–17 ноября, 9 дней)', start: nov.start, end: nov.end, duration: 9 },
    { id: 'winter_break', name: 'Зимний перерыв в РПЛ (14 декабря — 27 февраля)', start: winter.start, end: winter.end },
    { id: 'ib_mar', name: 'Пауза на сборные (23–31 марта, 9 дней)', start: mar.start, end: mar.end, duration: 9 },
    { id: 'ib_jun', name: 'Пауза на сборные (1–9 июня, 9 дней)', start: jun.start, end: jun.end, duration: 9 }
  ];
}

const DEFAULT_INTERNATIONAL_BREAKS = getSeasonBreaks(2026);

function isInInternationalBreak(dateStr: string): boolean {
  if (!dateStr || !db?.internationalBreaks) return false;
  return db.internationalBreaks.some((b: any) => dateStr >= b.start && dateStr <= b.end);
}

function getFixtureTourKey(f: any): string {
  const s = f.season || S();
  if (f.comp === 'rpl') return `${s}:rpl:${f.round}`;
  if (f.comp === 'cup') {
    const p = f.cupPath || (f.round <= 6 ? 'rpl_group' : 'regions_qual');
    const r = f.qualRound || f.round || f.cupStage || 1;
    return `${s}:cup:${p}:${r}`;
  }
  return `${s}:${f.comp}:${f.round || 1}`;
}

function assignTourReferees(tourList: any[]) {
  const validMatches = tourList.filter(f => f.comp === 'rpl' || f.comp === 'cup');
  const invalidMatches = tourList.filter(f => f.comp !== 'rpl' && f.comp !== 'cup');
  for (const f of invalidMatches) {
    delete f.refereeId;
    delete f.refereeName;
    delete f.assistants;
    delete f.reserveReferee;
    delete f.varReferee;
    delete f.avarReferee;
  }
  if (!validMatches.length || !db?.referees?.length) return;

  const usedHeadIds = new Set<string>();
  const comp = validMatches[0].comp;
  let eligible = db.referees.filter((r: any) => !r.leagues || r.leagues.includes(comp));
  if (!eligible.length) eligible = db.referees;

  // Сортируем матчи тура по важности (дерби и рейтинг команд)
  const teamPower = (tid: string) => {
    const ps = db.players.filter((p: any) => p.teamId === tid);
    if (!ps.length) return 70;
    return ps.reduce((s: number, p: any) => s + (p.rating || 70), 0) / ps.length;
  };
  const sortedMatches = [...validMatches].sort((a: any, b: any) => {
    const aDerby = db.derbies?.some((x: any) => (x.a === a.home && x.b === a.away) || (x.a === a.away && x.b === a.home)) ? 1 : 0;
    const bDerby = db.derbies?.some((x: any) => (x.a === b.home && x.b === b.away) || (x.a === b.away && x.b === b.home)) ? 1 : 0;
    if (bDerby !== aDerby) return bDerby - aDerby;
    return (teamPower(b.home) + teamPower(b.away)) - (teamPower(a.home) + teamPower(a.away));
  });

  // Шаг 1. Распределяем главных арбитров по рейтингу (каждый арбитр — строго на 1 матч в туре, по возможности не из города играющих команд)
  for (const f of sortedMatches) {
    let pool = eligible.filter((r: any) => !usedHeadIds.has(r.id));
    if (!pool.length) pool = eligible;
    const homeCity = (team(f.home)?.city || '').trim().toLowerCase();
    const awayCity = (team(f.away)?.city || '').trim().toLowerCase();
    const nonSameCity = pool.filter((r: any) => {
      const rc = (r.city || '').trim().toLowerCase();
      if (!rc) return true;
      return rc !== homeCity && rc !== awayCity;
    });
    const candidatePool = nonSameCity.length ? nonSameCity : pool;
    const sorted = [...candidatePool].sort((a: any, b: any) => (b.rating || 0) - (a.rating || 0));
    const chosen = sorted[0];
    if (chosen) {
      f.refereeId = chosen.id;
      f.refereeName = chosen.name;
      usedHeadIds.add(chosen.id);
    }
  }

  // Шаг 2. Главные арбитры больше ничего в этом туре не судят!
  const allHeadNames = new Set(validMatches.map(f => f.refereeName).filter(Boolean));
  const nonHeadRefs = db.referees.filter((r: any) => !usedHeadIds.has(r.id) && !allHeadNames.has(r.name));
  const nonHeadPool = nonHeadRefs.length ? nonHeadRefs : db.referees.filter((r: any) => !usedHeadIds.has(r.id));

  // Ассистенты арбитра
  const asstPool = (db.assistants || []).length ? db.assistants : ASSISTANT_REFEREES.map((n, i) => ({ id: 'asst_' + i, name: n }));
  const shuffledAssts = [...asstPool].sort(() => Math.random() - 0.5);
  let asstIdx = 0;

  for (const f of validMatches) {
    const a1 = shuffledAssts[asstIdx % shuffledAssts.length]?.name || 'Дмитрий Мосякин';
    const a2 = shuffledAssts[(asstIdx + 1) % shuffledAssts.length]?.name || 'Егор Болховитин';
    asstIdx += 2;
    f.assistants = [a1, a2];

    // Резервный арбитр (строго из не-главных арбитров тура)
    const resList = nonHeadPool.filter((r: any) => r.id !== f.refereeId);
    const chosenRes = resList.find((r: any) => r.role === 'Резервный судья') || resList[Math.floor(Math.random() * resList.length)];
    f.reserveReferee = chosenRes?.name || 'Вера Опейкина';

    // ВАР арбитр (строго из не-главных арбитров тура)
    let varList = nonHeadPool.filter((r: any) => r.varRole && r.id !== f.refereeId && r.name !== f.reserveReferee);
    if (!varList.length) varList = nonHeadPool.filter((r: any) => r.name !== f.reserveReferee);
    const chosenVar = varList[Math.floor(Math.random() * varList.length)];
    f.varReferee = chosenVar?.name || 'Сергей Карасев';

    // АВАР арбитр (строго из не-главных арбитров тура)
    let avarList = nonHeadPool.filter((r: any) => r.id !== f.refereeId && r.name !== f.reserveReferee && r.name !== f.varReferee);
    if (!avarList.length) avarList = nonHeadPool;
    const chosenAvar = avarList[Math.floor(Math.random() * avarList.length)];
    f.avarReferee = chosenAvar?.name || 'Павел Кукуян';
  }
}

function assignReferee(f: any, siblingList?: any[]) {
  // Арбитры назначаются ТОЛЬКО на матчи РПЛ и Кубка России; для остальных лиг арбитры не назначаются
  if (f.comp !== 'rpl' && f.comp !== 'cup') {
    delete f.refereeId;
    delete f.refereeName;
    delete f.assistants;
    delete f.reserveReferee;
    delete f.varReferee;
    delete f.avarReferee;
    return;
  }
  if (!db?.referees?.length) return;

  const tourKey = getFixtureTourKey(f);
  const validSiblings = Array.isArray(siblingList) ? siblingList : db.fixtures || [];
  const siblings = validSiblings.filter((x: any) => x.id !== f.id && getFixtureTourKey(x) === tourKey);
  assignTourReferees([f, ...siblings]);
}

function updateRefereeStats(f: any, events: any[] = []) {
  if (!f?.refereeId || !db?.referees) return;
  const r = db.referees.find((x: any) => x.id === f.refereeId);
  if (!r) return;
  const yc = events.filter((e: any) => e.type === 'yellow').length;
  const rc = events.filter((e: any) => e.type === 'red').length;
  const pen = events.filter((e: any) => e.type === 'pen_goal' || e.type === 'pen_miss').length;
  r.matches = (r.matches || 0) + 1;
  r.yellows = (r.yellows || 0) + yc;
  r.reds = (r.reds || 0) + rc;
  r.penalties = (r.penalties || 0) + pen;
  const base = r.rating > 0 ? r.rating : 7.5;
  const delta = yc <= 4 && rc === 0 ? 0.1 : rc > 0 ? -0.1 : 0.05;
  r.rating = Math.min(9.9, Math.max(5.5, +(base + delta).toFixed(1)));
  if (Array.isArray(f.assistants) && db.assistants) {
    for (const aname of f.assistants) {
      const a = db.assistants.find((x: any) => x.name === aname);
      if (a) {
        a.matches = (a.matches || 0) + 1;
        a.rating = a.rating > 0 ? Math.min(9.9, +(a.rating + 0.05).toFixed(1)) : 7.5;
      }
    }
  }
}

function assignFixtureWeather(f: any) {
  if (!f) return f;
  const homeTeam = (db?.teams || []).find((t: any) => t.id === f.home);
  const matchCity = f.city || homeTeam?.city || 'Москва';
  const matchDate = f.gameDate || f.date || '2026-09-15';
  const matchTime = f.gameTime || f.time || '17:00';
  const w = calculateMatchWeather(matchCity, matchDate, matchTime);
  f.weather = w.text;
  f.weatherShort = w.short;
  f.weatherDetails = {
    temp: w.temp,
    feelsLike: w.feelsLike,
    condition: w.condition,
    icon: w.icon,
    wind: w.wind,
    windDir: w.windDir,
    humidity: w.humidity,
    pressure: w.pressure,
    precipitation: w.precipitation,
    pitch: w.pitch
  };
  if (db?.dailyWeather) {
    db.dailyWeather[`${matchCity}_${matchDate}`] = w;
  }
  return f;
}

let db: any;
let PG_STATE: any = null; // база, прочитанная из PostgreSQL при старте
function load() {
  try {
    if (PG_STATE) { db = PG_STATE; PG_STATE = null; }
    else if (pgActive) db = seed(); // PostgreSQL подключён, но данных в нём ещё нет — чистая база
    else db = JSON.parse(fs.readFileSync(DB_FILE, 'utf8'));
  } catch {
    db = seed();
  }
  const def = seed();
  for (const k of Object.keys(def.settings)) {
    if (db.settings[k] === undefined) db.settings[k] = def.settings[k];
  }
  // Старый лимит заявки (25) поднимаем до 28
  if (db.settings.squadMax === 25) db.settings.squadMax = 28;
  for (const k of ['comps', 'teams', 'players', 'fixtures', 'derbies', 'transfers', 'llmlog', 'tournaments', 'transferRequests', 'budgetHistory', 'staffOffers', 'staffRoles', 'insiderPosts', 'eskCases']) {
    if (!Array.isArray(db[k])) db[k] = [];
  }
  if (!db.insiderPosts.length) db.insiderPosts = getInitialInsiderPosts();
  if (!db.eskCases.length) db.eskCases = getInitialEskCases();
  if (!db.referees || db.referees.length < 26) db.referees = JSON.parse(JSON.stringify(DEFAULT_REFEREES));
  if (!db.assistants || !db.assistants.length) {
    db.assistants = ASSISTANT_REFEREES.map((name, i) => ({
      id: 'asst_' + (i + 1),
      name,
      rating: 0,
      matches: 0,
      bio: 'Нажмите «Сделать портрет (ИИ)», чтобы сформировать подробное портфолио ассистента.'
    }));
  }
  const yCur = parseInt(String(db.settings?.season || S()).slice(0, 4), 10) || 2026;
  const currentSeasonBreaks = getSeasonBreaks(yCur);
  const hasLegacyBreaks = (db.internationalBreaks || []).some((b: any) => b.id === 'ib_sep' || b.id === 'ib_oct' || (b.id && String(b.id).includes('_2025')));
  if (!db.internationalBreaks || !db.internationalBreaks.length || hasLegacyBreaks) {
    db.internationalBreaks = JSON.parse(JSON.stringify(currentSeasonBreaks));
  } else {
    for (const def of currentSeasonBreaks) {
      if (!db.internationalBreaks.some((b: any) => b.id === def.id)) {
        db.internationalBreaks.push(JSON.parse(JSON.stringify(def)));
      }
    }
  }
  ensureSeasonFriendlies(yCur);
  for (const k of ['squads', 'lineups', 'tactics', 'sessions']) {
    if (!db[k]) db[k] = {};
  }
  if (!db.cityClimates || !Object.keys(db.cityClimates).length) {
    db.cityClimates = CLIMATE_DATA;
  }
  if (!db.dailyWeather) db.dailyWeather = {};

  // Синхронизируем географию команд для всех лиг
  for (const t of (db.teams || [])) {
    const geo = (ALL_TEAMS_GEO as any)[t.name];
    if (geo) {
      if (!t.city) t.city = geo.city;
      if (!t.stadium) t.stadium = geo.stadium;
      if (t.lat == null) t.lat = geo.lat;
      if (t.lon == null) t.lon = geo.lon;
    } else if (!t.city) {
      t.city = 'Москва';
      t.lat = 55.75;
      t.lon = 37.62;
    }
  }
  if (!db.foreignOffers) db.foreignOffers = [];

  // Привязываем погоду ко всем матчам
  for (const f of (db.fixtures || [])) {
    if (!f.weather) {
      assignFixtureWeather(f);
    }
  }

  // 1. Очищаем арбитров во всех лигах, кроме РПЛ и Кубка России
  for (const f of db.fixtures) {
    if (f.comp !== 'rpl' && f.comp !== 'cup') {
      delete f.refereeId;
      delete f.refereeName;
      delete f.assistants;
      delete f.reserveReferee;
      delete f.varReferee;
      delete f.avarReferee;
    }
  }

  // 2. В РПЛ и Кубке России: группируем по турам и переназначаем судей
  // Правило: главный арбитр может быть назначен только на 1 матч в туре, больше ничего в туре не судит
  const tours: Record<string, any[]> = {};
  for (const f of db.fixtures) {
    if (f.comp === 'rpl' || f.comp === 'cup') {
      const k = getFixtureTourKey(f);
      tours[k] = tours[k] || [];
      tours[k].push(f);
    }
  }

  for (const list of Object.values(tours)) {
    assignTourReferees(list);
  }
  save();

  // Синхронизируем список соревнований
  db.comps = COMPS;

  // Карта принадлежности команд к лигам по новому регламенту 2026/2027
  const wantedMap = new Map<string, { comp: string; city?: string; stadium?: string; lat?: number | null; lon?: number | null }>();
  for (const [name, city, lat, lon, stadium] of RPL) wantedMap.set(name, { comp: 'rpl', city, stadium, lat, lon });
  for (const [name, city, lat, lon, stadium] of FNL_TEAMS) wantedMap.set(name, { comp: 'fnl', city, stadium, lat, lon });
  for (const c of Object.keys(LOWER)) {
    for (const name of LOWER[c]) wantedMap.set(name, { comp: c });
  }

  // Убираем клубы, исключённые из лиг (только «пустые»: без игроков, матчей, заявки и штаба)
  for (const name of DROPPED_TEAMS) {
    if (wantedMap.has(name)) continue;
    const dt = db.teams.find((x: any) => x.name === name);
    if (!dt) continue;
    const busy = db.players.some((pl: any) => pl.teamId === dt.id)
      || db.fixtures.some((fx: any) => fx.home === dt.id || fx.away === dt.id)
      || (db.squads?.[dt.id] || []).length > 0
      || (db.staff || []).some((sm: any) => sm.teamId === dt.id);
    if (busy) { console.warn(`[лиги] «${name}» исключён из лиг, но за клубом есть игроки/матчи/штаб — оставлен, уберите вручную`); continue; }
    db.teams = db.teams.filter((x: any) => x.id !== dt.id);
    for (const k of ['squads', 'tactics']) if (db[k]) delete db[k][dt.id];
    db.derbies = (db.derbies || []).filter((d: any) => d.a !== dt.id && d.b !== dt.id);
  }

  // Дедуплицируем db.teams по имени (оставляя существующие команды с логотипами и добавляя недостающие)
  const UPPER_DUPES = new Set(['2DROTS', 'АМКАЛ', 'BROKE BOYS', 'LIT ENERGY', 'СИНДЕКАТ', 'СКА РОСТОВ', 'НАРОДНАЯ КОМАНДА', 'FIGHT NIGHTS', 'PRIME SQUAD', 'ФК Апсны', 'ФК МАТЧ']);
  const seenNames = new Set<string>();
  db.teams = db.teams.filter((t: any) => {
    if (UPPER_DUPES.has(t.name)) return false;
    const key = String(t.name || '').toLowerCase().trim();
    if (seenNames.has(key)) return false;
    seenNames.add(key);
    return true;
  });

  // Обновляем лиги и данные существующих команд
  for (const t of db.teams) {
    if (wantedMap.has(t.name)) {
      const w = wantedMap.get(t.name)!;
      t.comp = w.comp;
      if (w.city) t.city = w.city;
      if (w.stadium) t.stadium = w.stadium;
      if (w.lat != null) t.lat = w.lat;
      if (w.lon != null) t.lon = w.lon;
    }
    t.logo = getTeamLogo(t.name, t.logo, t.comp);
  }

  // Добавляем новые команды в базу
  for (const [name, w] of wantedMap.entries()) {
    if (!db.teams.some((t: any) => t.name === name)) {
      const geo: any = (ALL_TEAMS_GEO as any)[name] || {};
      db.teams.push({
        id: uid(),
        name,
        comp: w.comp,
        city: w.city || geo.city || '',
        lat: w.lat ?? geo.lat ?? null,
        lon: w.lon ?? geo.lon ?? null,
        stadium: w.stadium || geo.stadium || '',
        code: (w.comp === 'rpl' || w.comp === 'fnl') ? mkCode() : '',
        logo: getTeamLogo(name, null, w.comp)
      });
    }
  }

  // Обновляем дерби
  const T = (n: string) => db.teams.find((t: any) => t.name === n);
  {
    const customDerbies = (db.derbies || []).filter((d: any) => d.custom && db.teams.some((t: any) => t.id === d.a) && db.teams.some((t: any) => t.id === d.b));
    db.derbies = [...buildDerbyList(T), ...customDerbies];
  }

  // Инициализируем тренеров и тренерский штаб клубов
  if (db.settings.noAutoStaff) {
    // Тренеры и штабы удалены вручную — сервер больше не создаёт их автоматически (добавляются только через админку)
    if (!Array.isArray(db.staff)) db.staff = [];
  } else if (!db.staff || !Array.isArray(db.staff) || db.staff.length < 50) {
    db.staff = getAllInitialStaff(db.teams);
  } else {
    const existingTeamIds = new Set(db.staff.map((s: any) => s.teamId));
    for (const t of db.teams) {
      if (!existingTeamIds.has(t.id)) {
        db.staff.push(...generateClubStaff(t));
      }
    }
  }
  const hasRplSchedule = db.fixtures.some((f: any) => f.comp === 'rpl' && f.season === S());
  if (!db.settings.scheduleCleared && (!hasRplSchedule || !db.cupState2026)) {
    genSeason('2026-07-18', S());
  } else if (db.cupState2026 && db.fixtures.length) {
    recalculateCupGroups(db.cupState2026, db.fixtures);
  }

  loadCodeRegistry();
  ensureTeamCodes();
  ensureInitialBudgets();
  for (const s of getAvailableSeasons()) {
    ensureSuperCupFixture(s);
  }
  save();
}

let saveT: NodeJS.Timeout | null = null;
function save() {
  if (saveT) return;
  saveT = setTimeout(saveNow, 250);
}
function saveNow() {
  saveT = null;
  try {
    if (db && Array.isArray(db.fixtures)) {
      for (const f of db.fixtures) {
        if (!f.weather) assignFixtureWeather(f);
      }
    }
    db._savedAt = Date.now();
    if (pgActive) { pgQueueState(() => db); return; } // PostgreSQL: пишутся только изменившиеся строки
    fs.writeFileSync(DB_FILE + '.tmp', JSON.stringify(db));
    fs.renameSync(DB_FILE + '.tmp', DB_FILE);
  } catch (e: any) {
    console.error('save:', e.message);
  }
}

const mcache = new Map<string, any>();
const getMatch = (id: string) => {
  if (mcache.has(id)) return mcache.get(id);
  if (pgActive) return null; // все матчи загружены из PostgreSQL при старте
  try {
    const m = JSON.parse(fs.readFileSync(path.join(MDIR, id + '.json'), 'utf8'));
    mcache.set(id, m);
    if (mcache.size > 40) mcache.delete(mcache.keys().next().value!);
    return m;
  } catch {
    return null;
  }
};
const putMatch = (id: string, m: any) => {
  mcache.set(id, m);
  if (pgActive) { pgQueueMatch(id, () => m); return; }
  fs.writeFileSync(path.join(MDIR, id + '.json'), JSON.stringify(m));
};

/* ───────── доступ к данным ───────── */
const S = () => db.settings.season;
const team = (id: string) => db.teams.find((t: any) => t.id === id);
const tn = (id: string) => team(id)?.name || '?';
const teamLogo = (id: string) => {
  const t = team(id);
  if (!t) return getTeamLogo('?');
  const official = getTeamLogo(t.name, null, t.comp);
  return official.startsWith('/assets/') ? official : (t.logo || official);
};
const player = (id: string) => db.players.find((p: any) => p.id === id);
const fx = (id: string) => db.fixtures.find((f: any) => f.id === id);
const compOf = (id: string) => db.comps.find((c: any) => c.id === id);
const seasonFx = () => db.fixtures.filter((f: any) => f.season === S());
const GROUP: Record<string, string> = { ВР: 'gk', ЦЗ: 'def', ЛЗ: 'def', ПЗ: 'def', ОП: 'mid', ЦП: 'mid', АП: 'mid', ЛВ: 'fwd', ПВ: 'fwd', ЦФ: 'fwd' };
const POSES = Object.keys(GROUP);
function squadOf(tid: string) {
  const ids = db.squads[tid];
  return (ids ? ids.map(player) : db.players.filter((p: any) => p.teamId === tid)).filter(Boolean);
}
/* ───────── дубли и молодёжки: один клуб — несколько команд ───────── */
/** id всех команд клуба (включая саму команду). Для команд без дублей — [tid]. */
function clubFamilyOf(tid: string): string[] {
  const t = team(tid);
  if (!t) return [tid];
  const ids = familyNamesOf(t.name).map(n => db.teams.find((x: any) => x.name === n)?.id).filter(Boolean) as string[];
  return ids.includes(tid) ? ids : [tid];
}
const sisterIdsOf = (tid: string) => clubFamilyOf(tid).filter(id => id !== tid);
/** Игрок уже заявлен (старт/скамейка) за другую команду клуба на матч в этот же день. Возвращает название этой команды. */
function loanBusyWith(pid: string, date: string, tid: string): string | null {
  const sis = sisterIdsOf(tid);
  if (!sis.length) return null;
  for (const g of db.fixtures) {
    if (g.date !== date) continue;
    for (const side of ['home', 'away']) {
      const gt = g[side];
      if (!sis.includes(gt)) continue;
      const L = db.lineups[g.id + ':' + gt];
      if (L && ((L.starters || []).includes(pid) || (L.bench || []).includes(pid))) return tn(gt);
    }
  }
  return null;
}
/** Игроки заявок других команд клуба, которых можно взять на матч f (с флагами доступности). */
function loanPoolFor(tid: string, f: any) {
  const out: any[] = [];
  for (const sid of sisterIdsOf(tid)) {
    for (const p of squadOf(sid)) {
      out.push({ p, from: sid, available: isAvail(p, f.date), busyWith: loanBusyWith(p.id, f.date, tid) });
    }
  }
  return out;
}
/** Если игрок команды tid в этом матче — «гость» из дубля/основы, возвращает название его команды. */
function loanFromName(tid: string, pid: string): string | null {
  if (squadOf(tid).some((x: any) => x.id === pid)) return null;
  for (const sid of sisterIdsOf(tid)) if (squadOf(sid).some((x: any) => x.id === pid)) return tn(sid);
  return null;
}

function isAvail(p: any, date: string) {
  if (!p) return false;
  if (p.banLeft > 0) return false;
  if (p.banUntil && p.banUntil >= date) return false;
  if (p.out && p.out.until >= date) return false;
  return true;
}
/* ───────── дисциплина: сроки дисквалификаций и травм в «родных» единицах ───────── */
const ruPlural = (n: number, a: string, b: string, c: string) => {
  const m = Math.abs(n) % 100, d = m % 10;
  return m > 10 && m < 20 ? c : d === 1 ? a : d >= 2 && d <= 4 ? b : c;
};
const ruDateStr = (d: string) => { const [y, m, dd] = String(d || '').split('-'); return y && m && dd ? `${dd}.${m}.${y}` : String(d || ''); };
/* срок в днях → «3 месяца» / «2 недели» / «10 дней» */
function daysLabel(d: number): string {
  d = Math.max(1, Math.round(d));
  if (d >= 45) { const n = Math.round(d / 30); return `${n} ${ruPlural(n, 'месяц', 'месяца', 'месяцев')}`; }
  if (d >= 14) { const n = Math.round(d / 7); return `${n} ${ruPlural(n, 'неделя', 'недели', 'недель')}`; }
  return `${d} ${ruPlural(d, 'день', 'дня', 'дней')}`;
}
/* дисквалификация: «1 матч», «3 матча», «до 15.01.2027 (2 месяца), все турниры» */
function banText(p: any, date?: string): string {
  if (!p) return '';
  const parts: string[] = [];
  if (p.banLeft > 0) parts.push(`${p.banLeft} ${ruPlural(p.banLeft, 'матч', 'матча', 'матчей')}`);
  if (p.banUntil && (!date || p.banUntil >= date)) parts.push(`до ${ruDateStr(p.banUntil)}${p.banLabel ? ` (${p.banLabel})` : ''}, все турниры`);
  return parts.join(' + ');
}
/* травма: «3 месяца (до 10.02.2027)» */
function outText(p: any, date?: string): string {
  if (!p || !p.out || !p.out.until) return '';
  if (date && p.out.until < date) return '';
  const lbl = p.out.label || (p.out.days ? daysLabel(p.out.days) : '');
  return `${lbl ? lbl + ' ' : ''}(до ${ruDateStr(p.out.until)})`.trim();
}
function unavailText(p: any, date: string): string {
  const out: string[] = [];
  const b = banText(p, date);
  if (b) out.push(`дисквалификация: ${b}${p.banReason ? ` — ${p.banReason}` : ''}`);
  const o = outText(p, date);
  if (o) out.push(`травма: ${o}`);
  return out.join('; ');
}
/* дисциплина главного тренера и штаба (жёлтые/красные получают не только футболисты) */
function discKey(tid: string, name: string) { return `${tid}|${norm(name)}`; }
function getDisc(tid: string, name: string) {
  if (!db.staffDiscipline || typeof db.staffDiscipline !== 'object') db.staffDiscipline = {};
  const k = discKey(tid, name);
  if (!db.staffDiscipline[k]) db.staffDiscipline[k] = { tid, name, yc: 0, banLeft: 0, reason: '' };
  return db.staffDiscipline[k];
}
function bannedStaffText(tid: string): string[] {
  const out: string[] = [];
  for (const d of Object.values<any>(db.staffDiscipline || {})) {
    if (d.tid === tid && d.banLeft > 0) out.push(`${d.name} — дисквалифицирован ещё на ${d.banLeft} ${ruPlural(d.banLeft, 'матч', 'матча', 'матчей')}${d.reason ? ` (${d.reason})` : ''}, на скамейке и в технической зоне отсутствует`);
  }
  return out;
}
/* Сегодняшняя дата (YYYY-MM-DD) по Москве */
function todayMsk(): string {
  try {
    return new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Moscow', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  } catch {
    return new Date().toISOString().slice(0, 10);
  }
}
/* Возраст на дату: если известна полная дата рождения (YYYY-MM-DD) — год прибавляется ровно в день рождения; если только год — разница лет */
function ageOn(born: any, date?: string): number | null {
  const m = String(born || '').match(/^(\d{4})(?:-(\d{2})-(\d{2}))?/);
  if (!m) return null;
  const on = String(date || todayMsk()).slice(0, 10);
  let a = +on.slice(0, 4) - +m[1];
  if (m[2] && m[3] && on.slice(5, 10) < `${m[2]}-${m[3]}`) a--;
  return a;
}
function ageOfPlayer(p: any, date?: string): number | null {
  const a = ageOn(p?.born, date);
  return a !== null ? a : (p?.age != null ? Number(p.age) : null);
}
function isBirthdayToday(p: any): boolean {
  const m = String(p?.born || '').match(/^\d{4}-(\d{2}-\d{2})/);
  return !!m && m[1] === todayMsk().slice(5, 10);
}
/* Обновляет сохранённое поле age у игроков, у которых наступил день рождения. Возвращает число изменённых. */
function syncPlayerAges(): number {
  let n = 0;
  for (const p of (db?.players || [])) {
    const a = ageOn(p.born);
    if (a !== null && a >= 14 && a <= 55 && p.age !== a) { p.age = a; n++; }
  }
  return n;
}
function age(p: any, date: string) {
  return ageOn(p.born, date);
}
function roundLabel(f: any) {
  if (f.label) return f.label;
  if (f.comp === 'supercup') return 'Матч за Суперкубок России';
  if (f.comp === 'cup') {
    if (f.cupPath === 'superfinal' || f.cupStage === 'superfinal') {
      return 'Суперфинал FONBET Кубка России';
    }
    if (f.cupPath === 'rpl_group') {
      return `Путь РПЛ · ${f.round}-й тур`;
    }
    if (f.cupPath === 'regions_qual') {
      return `Путь регионов · ${f.qualRound || f.round}-й отборочный раунд`;
    }
    if (f.cupPath === 'rpl_playoff') {
      return `Путь РПЛ · 1/8 финала`;
    }
    if (f.cupPath === 'regions_playoff') {
      return `Путь регионов · 1/8 финала`;
    }
    const n = seasonFx().filter((x: any) => x.comp === 'cup' && x.round === f.round).length;
    return ({ 16: '1/16 финала', 8: '1/8 финала', 4: '1/4 финала', 2: 'Полуфинал', 1: 'Финал' } as any)[n] || `Раунд ${f.round}`;
  }
  return `${f.round}-й тур`;
}
const compName = (f: any) => compOf(f.comp)?.name || f.comp;
const winnerOf = (f: any) => f.hg > f.ag ? f.home : f.hg < f.ag ? f.away : (f.pen ? (f.pen.winner === 'home' ? f.home : f.away) : null);

/* ───────── трансферы, топовые переходы и ИИ-советник ───────── */
function parseFeeAmount(feeStr: any): number {
  if (typeof feeStr === 'number') return feeStr;
  const s = String(feeStr || '').trim();
  const numMatch = s.match(/([0-9]+(?:[.,][0-9]+)?)/);
  if (!numMatch) return 0;
  let val = parseFloat(numMatch[1].replace(',', '.'));
  if (/тыс|k|k\b/i.test(s) && !/млн|m|m\b/i.test(s)) {
    val = val / 1000;
  } else if (/млрд|b|b\b/i.test(s)) {
    val = val * 1000;
  }
  if (/₽|руб/i.test(s)) {
    val = val / 100;
  }
  return Math.round(val * 100) / 100;
}

function executeTransferIfBothApproved(t: any): boolean {
  if (t.status === 'approved') return true;
  const needClub = !!t.isRplToRpl;
  const clubOk = !needClub || t.clubApproval === 'approved';
  const adminOk = t.adminApproval === 'approved';

  if (clubOk && adminOk) {
    t.status = 'approved';
    const p = player(t.pid);
    if (p) {
      if (t.from && db.squads[t.from]) {
        db.squads[t.from] = db.squads[t.from].filter((id: string) => id !== p.id);
      }
      db.squads[t.to] = [...new Set([...squadOf(t.to).map((x: any) => x.id), p.id])];
      p.teamId = t.to;
      const isMandatoryBuyout = !!(t.mandatoryBuyoutOnRplRetention || t.mandatoryBuyout || t.type === 'loan_mandatory_rpl');
      const loanCond = t.loanCondition || (isMandatoryBuyout ? 'Сохранение прописки в РПЛ' : null);
      if (t.type === 'loan' || isMandatoryBuyout) {
        p.loanFrom = t.fromName || (t.from ? tn(t.from) : 'Клуб');
        p.loanFromId = t.from;
        p.loanTerm = t.note || (isMandatoryBuyout ? `Аренда с обязательным выкупом (${t.buyoutFee || '€8.0M'})${loanCond ? ` при условии: «${loanCond}»` : ''}` : 'Аренда');
        if (isMandatoryBuyout) {
          p.mandatoryBuyoutOnRplRetention = true;
          p.mandatoryBuyout = true;
          p.buyoutFee = t.buyoutFee || t.fee || '€8.0M';
          p.loanCondition = loanCond || 'Обязательный выкуп контракта';
        }
      } else {
        delete p.loanFrom;
        delete p.loanFromId;
        delete p.loanTerm;
        delete p.mandatoryBuyoutOnRplRetention;
        delete p.mandatoryBuyout;
        delete p.buyoutFee;
        delete p.loanCondition;
      }

      // Обмен игроками (swap deal)
      let pSwap: any = null;
      if (t.type === 'exchange' && t.exchangePid) {
        pSwap = player(t.exchangePid);
        if (pSwap) {
          if (t.to && db.squads[t.to]) {
            db.squads[t.to] = db.squads[t.to].filter((id: string) => id !== pSwap.id);
          }
          db.squads[t.from] = [...new Set([...squadOf(t.from).map((x: any) => x.id), pSwap.id])];
          pSwap.teamId = t.from;
        }
      }

      t.statsForNewClub = {
        matches: p.matches || 0,
        goals: p.goals || 0,
        assists: p.assists || 0,
        rating: Number(p.rating || 7.0),
        impactScore: ((p.goals || 0) * 4 + (p.assists || 0) * 2.5 + (p.matches || 0) * 1.2 + ((p.rating || 7.0) >= 6.5 ? ((p.rating || 7.0) - 6.0) * 10 : 0)),
        summary: `${p.goals || 0} голов, ${p.assists || 0} ассистов в ${p.matches || 0} матчах`
      };

      const feeAmt = t.feeAmount !== undefined ? t.feeAmount : parseFeeAmount(t.fee);
      const buyer = team(t.to);
      const seller = team(t.from);

      if (feeAmt && feeAmt > 0) {
        const feeEuros = Math.round(feeAmt * 1_000_000);
        if (buyer) {
          const prev = buyer.budget || 0;
          buyer.budget = Math.max(0, prev - feeEuros);
          if (!Array.isArray(db.budgetHistory)) db.budgetHistory = [];
          db.budgetHistory.push({
            id: uid(),
            teamId: buyer.id,
            teamName: buyer.name,
            amount: -feeEuros,
            prevBudget: prev,
            newBudget: buyer.budget,
            type: t.type === 'exchange' ? 'transfer_exchange' : (isMandatoryBuyout ? 'transfer_loan_mandatory' : 'transfer_buy'),
            typeLabel: t.type === 'exchange' ? 'Обмен с доплатой' : (isMandatoryBuyout ? 'Аренда с обязат. выкупом в РПЛ' : 'Покупка игрока'),
            description: t.type === 'exchange'
              ? `Обмен: получен ${p.name}, отдан ${pSwap?.name || 'игрок'} + доплата (-€${feeEuros.toLocaleString('ru-RU')}) в «${seller?.name || t.fromName}»`
              : `${isMandatoryBuyout ? 'Аренда с обязат. выкупом' : 'Трансфер'}: ${p.name} из «${seller?.name || t.fromName}» (-€${feeEuros.toLocaleString('ru-RU')})`,
            date: new Date().toISOString(),
            byAdmin: !!t.byAdmin
          });
        }

        // Проверяем наличие пункта о проценте с будущей перепродажи (Sell-on clause) от предыдущего клуба
        let sellOnPayout = 0;
        let sellOnClubObj: any = null;
        if (p.sellOnPercent && p.sellOnPercent > 0 && p.sellOnClubId && p.sellOnClubId !== seller?.id && p.sellOnClubId !== buyer?.id) {
          sellOnClubObj = team(p.sellOnClubId);
          if (sellOnClubObj) {
            sellOnPayout = Math.round(feeEuros * (Number(p.sellOnPercent) / 100));
          }
        }
        const netSellerIncome = Math.max(0, feeEuros - sellOnPayout);

        if (seller) {
          const prev = seller.budget || 0;
          seller.budget = prev + netSellerIncome;
          if (!Array.isArray(db.budgetHistory)) db.budgetHistory = [];
          db.budgetHistory.push({
            id: uid(),
            teamId: seller.id,
            teamName: seller.name,
            amount: netSellerIncome,
            prevBudget: prev,
            newBudget: seller.budget,
            type: t.type === 'exchange' ? 'transfer_exchange' : 'transfer_sell',
            typeLabel: t.type === 'exchange' ? 'Обмен с доплатой' : 'Продажа игрока',
            description: t.type === 'exchange'
              ? `Обмен: отдан ${p.name}, получен ${pSwap?.name || 'игрок'} + компенсация (+€${netSellerIncome.toLocaleString('ru-RU')}) от «${buyer?.name || t.toName}»`
              : `Продажа: ${p.name} в «${buyer?.name || t.toName}» (+€${netSellerIncome.toLocaleString('ru-RU')}${sellOnPayout > 0 ? `, за вычетом sell-on ${p.sellOnPercent}% в «${sellOnClubObj?.name}»: -€${sellOnPayout.toLocaleString('ru-RU')}` : ''})`,
            date: new Date().toISOString(),
            byAdmin: !!t.byAdmin
          });
        }

        if (sellOnPayout > 0 && sellOnClubObj) {
          const prevSoc = sellOnClubObj.budget || 0;
          sellOnClubObj.budget = prevSoc + sellOnPayout;
          if (!Array.isArray(db.budgetHistory)) db.budgetHistory = [];
          db.budgetHistory.push({
            id: uid(),
            teamId: sellOnClubObj.id,
            teamName: sellOnClubObj.name,
            amount: sellOnPayout,
            prevBudget: prevSoc,
            newBudget: sellOnClubObj.budget,
            type: 'sell_on_clause',
            typeLabel: 'Выплата по Sell-on clause',
            description: `Пункт о перепродаже (${p.sellOnPercent}%): продажа ${p.name} из «${seller?.name || t.fromName}» в «${buyer?.name || t.toName}» (+€${sellOnPayout.toLocaleString('ru-RU')})`,
            date: new Date().toISOString(),
            byAdmin: !!t.byAdmin
          });
        }
      }

      // Фиксируем новый sell-on clause, если он предусмотрен в текущем соглашении
      if (t.sellOnPercent && Number(t.sellOnPercent) > 0 && seller) {
        p.sellOnPercent = Number(t.sellOnPercent);
        p.sellOnClubId = seller.id;
        p.sellOnClubName = seller.name;
      }

      // Закрываем конкурирующие заявки на этого же игрока
      const buyerName = buyer?.name || t.toName || 'клуб';
      for (const other of (db.transfers || [])) {
        if (other.id !== t.id && other.pid === t.pid && other.status === 'pending') {
          other.status = 'rejected';
          other.rejectReason = `Игрок/клуб выбрал предложение «${buyerName}» (${t.fee || 'согласовано'})`;
        }
      }
      const pClean = (p.name || '').trim().toLowerCase();
      for (const req of (db.transferRequests || [])) {
        if (req.status === 'pending' && (req.playerName || '').trim().toLowerCase() === pClean) {
          req.status = 'rejected';
          req.rejectReason = `Игрок перешёл в «${buyerName}»`;
        }
      }
    }
    return true;
  }
  return false;
}

function formatTransferForPublic(t: any) {
  const fromT = team(t.from);
  const toT = team(t.to);
  const p = player(t.pid);
  const feeAmt = t.feeAmount !== undefined ? t.feeAmount : parseFeeAmount(t.fee);
  return {
    id: t.id,
    pid: t.pid,
    playerName: t.playerName || p?.name || 'Игрок',
    pos: t.pos || p?.pos || 'ЦП',
    from: t.from,
    fromName: fromT?.name || t.fromName || 'Клуб',
    fromLogo: teamLogo(t.from),
    to: t.to,
    toName: toT?.name || t.toName || 'Клуб',
    toLogo: teamLogo(t.to),
    fee: t.fee || (feeAmt ? `€${feeAmt.toFixed(1)}M` : 'Свободный агент'),
    feeAmount: feeAmt,
    type: t.type || 'transfer',
    mandatoryBuyoutOnRplRetention: !!(t.mandatoryBuyoutOnRplRetention || t.mandatoryBuyout || t.type === 'loan_mandatory_rpl'),
    mandatoryBuyout: !!(t.mandatoryBuyoutOnRplRetention || t.mandatoryBuyout || t.type === 'loan_mandatory_rpl'),
    buyoutFee: t.buyoutFee || null,
    loanCondition: t.loanCondition || (t.mandatoryBuyoutOnRplRetention || t.type === 'loan_mandatory_rpl' ? 'Сохранение прописки в РПЛ' : null),
    sellOnPercent: t.sellOnPercent ? Number(t.sellOnPercent) : 0,
    sellOnClubId: t.sellOnClubId || null,
    sellOnClubName: t.sellOnClubName || null,
    note: t.note || (t.mandatoryBuyoutOnRplRetention || t.type === 'loan_mandatory_rpl' ? `Аренда с обязательным выкупом (${t.buyoutFee || '€8.0M'})${t.loanCondition ? ` при условии: «${t.loanCondition}»` : ''}` : t.type === 'loan' ? 'Аренда' : 'Полноценный трансфер'),
    date: t.date || new Date().toISOString().slice(0, 10),
    isRplToRpl: !!t.isRplToRpl,
    stats: t.statsForNewClub || {
      matches: p?.matches || 0,
      goals: p?.goals || 0,
      assists: p?.assists || 0,
      rating: Number(p?.rating || 7.0),
      impactScore: ((p?.goals || 0) * 4 + (p?.assists || 0) * 2.5 + (p?.matches || 0) * 1.2),
      summary: `${p?.goals || 0} голов, ${p?.assists || 0} ассистов в ${p?.matches || 0} матчах`
    }
  };
}

function ensureInitialTransfers() {
  if (!db.transfers) db.transfers = [];
}


