/* ───────── Внутренний (негласный) турнир внутри РПЛ ─────────
   Участвуют только очные матчи РПЛ между клубами одной группы. Отдельных матчей нет —
   результаты берутся из обычного календаря РПЛ. Видно только админу. */
const INTERNAL_GROUPS: { id: string; name: string; teams: string[] }[] = [
  { id: 'moscow', name: 'Москва', teams: ['Спартак', 'Локомотив', 'Динамо Москва', 'ЦСКА', 'Родина'] },
  { id: 'volga', name: 'Волжские', teams: ['Акрон', 'Крылья Советов', 'Рубин'] },
  { id: 'south', name: 'ЮГ', teams: ['Краснодар', 'Ростов', 'Факел'] }
];
function internalTournament(season?: string) {
  const ssn = season || S();
  const rplFx = db.fixtures.filter((f: any) => f.comp === 'rpl' && f.season === ssn);
  return INTERNAL_GROUPS.map(g => {
    const ids = g.teams.map(n => db.teams.find((t: any) => t.name === n && t.comp === 'rpl')?.id).filter(Boolean) as string[];
    const idSet = new Set(ids);
    const R: Record<string, any> = {};
    ids.forEach(i => { R[i] = { id: i, name: tn(i), logo: teamLogo(i), p: 0, w: 0, d: 0, l: 0, gf: 0, ga: 0, pts: 0, form: [] as string[] }; });
    const games = rplFx
      .filter((f: any) => idSet.has(f.home) && idSet.has(f.away))
      .sort((a: any, b: any) => ((a.date || '') + (a.time || '')).localeCompare((b.date || '') + (b.time || '')));
    for (const f of games) {
      if (f.status !== 'done' || f.hg == null) continue;
      for (const [t, gf, ga] of [[f.home, f.hg, f.ag], [f.away, f.ag, f.hg]] as [string, number, number][]) {
        const r = R[t]; r.p++; r.gf += gf; r.ga += ga;
        if (gf > ga) { r.w++; r.pts += 3; r.form.push('В'); }
        else if (gf === ga) { r.d++; r.pts++; r.form.push('Н'); }
        else { r.l++; r.form.push('П'); }
      }
    }
    const rows = Object.values(R).sort((a: any, b: any) => b.pts - a.pts || b.w - a.w || (b.gf - b.ga) - (a.gf - a.ga) || b.gf - a.gf || a.name.localeCompare(b.name));
    rows.forEach((r: any, i: number) => { r.pos = i + 1; r.gd = r.gf - r.ga; r.form = r.form.slice(-5).join(''); });
    const missing = g.teams.filter(n => !db.teams.some((t: any) => t.name === n && t.comp === 'rpl'));
    return {
      id: g.id, name: g.name, rows, missing,
      total: games.length,
      played: games.filter((f: any) => f.status === 'done').length,
      games: games.map((f: any) => ({ id: f.id, date: f.date, time: f.time, round: f.round, home: f.home, away: f.away, homeName: tn(f.home), awayName: tn(f.away), status: f.status, hg: f.hg, ag: f.ag }))
    };
  });
}
