// Запуск прямого эфира трансляции администратором
app.post('/api/admin/draw/start', admin, (req: any, res) => {
  const tournament = req.body?.tournament || 'cup_rpl';
  db.liveDraw = {
    active: true,
    startedAt: new Date().toISOString(),
    tournament,
    stage: 'warmup',
    step: 0,
    warmupStep: 0,
    history: []
  };
  save();

  const appUrl = (process.env.APP_URL || db.settings?.siteUrl || 'http://localhost:3000').replace(/\/+$/, '');
  const tTitle = tournament === 'media_cup'
    ? 'Winline Кубка Медиалиги (MFL)'
    : tournament === 'cup_regions'
    ? 'FONBET Кубка России (Путь Регионов · Медиалига vs 2-я лига)'
    : 'FONBET Кубка России (Путь РПЛ)';

  try {
    tg(`🔴 <b>ПРЯМОЙ ЭФИР: ЖЕРЕБЬЁВКА ${tTitle.toUpperCase()} НАЧАЛАСЬ!</b>\n\n` +
       `🎙 Мы выходим в прямой ТВ-эфир из студии в Останкино! Ведущий Роман Нагучев и эксперты студии начинают пре-шоу, разогрев и обсуждение интриг турнира перед открытием лототрона.\n\n` +
       `📺 <b>Присоединяйтесь к прямой трансляции:</b>\n${appUrl}/#/draw`);
  } catch (err) {
    console.error('[Telegram Send Error]:', err);
  }

  res.json({ ok: 1, liveDraw: db.liveDraw });
});

// Завершение или остановка прямого эфира администратором
app.post('/api/admin/draw/stop', admin, (req: any, res) => {
  const wasActive = db.liveDraw?.active;
  if (!db.liveDraw) db.liveDraw = {};
  db.liveDraw.active = false;
  save();

  if (wasActive) {
    try {
      tg(`🏁 <b>Прямой эфир жеребьёвки завершён!</b>\nСпасибо всем зрителям трансляции!`);
    } catch (err) {}
  }

  res.json({ ok: 1 });
});

// Очистка / удаление сформированных групп и сеток жеребьевки (как сразу во всех 3 турнирах, так и выборочно в любом одном)
app.post('/api/admin/draw/clear-groups', admin, (req: any, res) => {
  const tournament = String(req.body?.tournament || 'all').toLowerCase();
  const cleared: string[] = [];

  // 1. FONBET Кубок России — Путь РПЛ
  if (tournament === 'all' || tournament === 'cup_rpl') {
    if (db.cupState2026) {
      db.cupState2026.rplGroups = {};
    }
    const before = db.fixtures.length;
    db.fixtures = db.fixtures.filter((f: any) => !(f.comp === 'cup' && f.cupPath === 'rpl_group'));
    const removed = before - db.fixtures.length;
    if (db.liveDraw?.tournament === 'cup_rpl') {
      db.liveDraw.active = false;
      db.liveDraw.step = 0;
      db.liveDraw.history = [];
    }
    cleared.push(`Кубок России (Путь РПЛ: очищены группы A, B, C, D и удалено ${removed} матчей)`);
  }

  // 2. FONBET Кубок России — Путь Регионов (1-й отборочный раунд)
  if (tournament === 'all' || tournament === 'cup_regions') {
    const before = db.fixtures.length;
    db.fixtures = db.fixtures.filter((f: any) => !(f.comp === 'cup' && f.cupPath === 'regions_qual' && f.qualRound === 1));
    const removed = before - db.fixtures.length;
    if (db.liveDraw?.tournament === 'cup_regions') {
      db.liveDraw.active = false;
      db.liveDraw.step = 0;
      db.liveDraw.history = [];
    }
    cleared.push(`Кубок России (Путь Регионов: удалено ${removed} матчей 1-го отборочного раунда)`);
  }

  // 3. Winline Кубок Медиалиги
  if (tournament === 'all' || tournament === 'media_cup') {
    const beforeT = (db.tournaments || []).length;
    db.tournaments = (db.tournaments || []).filter((t: any) => t.compId !== 'media_cup');
    const beforeF = db.fixtures.length;
    db.fixtures = db.fixtures.filter((f: any) => f.comp !== 'media_cup');
    const removed = beforeF - db.fixtures.length;
    if (db.liveDraw?.tournament === 'media_cup') {
      db.liveDraw.active = false;
      db.liveDraw.step = 0;
      db.liveDraw.history = [];
    }
    cleared.push(`Кубок Медиалиги (сетка/турнир удалены, очищено ${removed} матчей)`);
  }

  save();
  invalidateAgg();

  res.json({
    ok: 1,
    tournament,
    cleared,
    message: tournament === 'all'
      ? `Группы и сетки успешно удалены сразу во всех 3 турнирах:\n\n• ${cleared.join('\n• ')}`
      : `Результаты жеребьёвки успешно сброшены:\n${cleared.join('\n')}`
  });
});

// Отправка текстовых событий жеребьевки в Telegram (пре-шоу, вытянутые шары, финиш)
app.post('/api/draw/tg-event', (req: any, res) => {
  const { type, payload } = req.body || {};
  if (!type || !payload) return res.json({ ok: 1 });

  const appUrl = (process.env.APP_URL || db.settings?.siteUrl || 'http://localhost:3000').replace(/\/+$/, '');

  try {
    if (type === 'warmup') {
      const { speaker, role, text } = payload;
      tg(`🎙 <b>Пре-шоу жеребьёвки · ${esc(speaker)} (${esc(role)}):</b>\n\n` +
         `«${esc(text)}»\n\n` +
         `<i>Зрители подтягиваются к эфиру, до старта лототрона считанные минуты!</i>`);
    } else if (type === 'draw_start') {
      tg(`🎱 <b>ВНИМАНИЕ! Официальная часть жеребьёвки началась!</b>\n\n` +
         `Лототрон запущен, шары перемешиваются в чаше! Гости студии подходят к лототрону.\n\n` +
         `📺 <b>Смотрите прямой эфир:</b> ${appUrl}/#/draw`);
    } else if (type === 'ball') {
      const { teamName, slot, commentator, guest, isDerby } = payload;
      tg(`🎱 <b>Жеребьёвка · ${esc(slot)}</b>\n` +
         `Клуб: <b>${esc(teamName)}</b>\n` +
         (isDerby ? `\n🔥 <b>ВНИМАНИЕ, ДЕРБИ В ГРУППЕ!</b>\n` : '') +
         `\n🎙 <b>Комментарий студии:</b> «${esc(commentator)}»\n` +
         (guest ? `⭐ <b>Эксперт:</b> «${esc(guest)}»\n` : '') +
         `\n📺 <b>Прямой эфир:</b> ${appUrl}/#/draw`);
    } else if (type === 'finish') {
      const { tournamentName, summary } = payload;
      tg(`🏆 <b>ЖЕРЕБЬЁВКА «${esc(tournamentName)}» УСПЕШНО ЗАВЕРШЕНА!</b>\n\n` +
         `${esc(summary)}\n\n` +
         `📅 <b>Полное расписание матчей турнира:</b>\n${appUrl}/#/fixtures/cup`);
    }
  } catch (e) {
    console.error('[Draw Telegram Send Error]:', e);
  }

  res.json({ ok: 1 });
});

// Утверждение жеребьёвки Пути РПЛ
app.post('/api/admin/draw/apply-cup-rpl', admin, (req: any, res) => {
  const { groups } = req.body;
  if (!groups || !groups.A || !groups.B || !groups.C || !groups.D) {
    return fail(res, 'Необходимо предоставить составы всех 4 групп (A, B, C, D)');
  }

  const season = S();
  if (!db.cupState2026) advanceCup();

  const groupIds = ['A', 'B', 'C', 'D'];
  const rplGroups: any = {};
  for (const gid of groupIds) {
    const gTeams = groups[gid];
    if (!Array.isArray(gTeams) || gTeams.length !== 4) {
      return fail(res, `В группе ${gid} должно быть ровно 4 команды`);
    }
    rplGroups[gid] = {
      id: gid,
      name: `Группа ${gid}`,
      teams: gTeams,
      table: gTeams.map((tid: string, idx: number) => {
        const teamObj = team(tid);
        return {
          id: tid,
          name: teamObj?.name || tid,
          pos: idx + 1,
          p: 0,
          w: 0,
          d: 0,
          l: 0,
          gf: 0,
          ga: 0,
          gd: 0,
          pts: 0,
          zone: idx < 2 ? 'top' : idx === 2 ? 'playoff' : 'bad',
          zoneLabel: idx < 2 ? '1/8 Пути РПЛ' : idx === 2 ? 'В Путь регионов' : 'Вылет из турнира'
        };
      })
    };
  }

  db.cupState2026.rplGroups = rplGroups;

  // Удаляем старые групповые несыгранные матчи
  db.fixtures = db.fixtures.filter((f: any) => !(f.comp === 'cup' && f.cupPath === 'rpl_group' && f.status !== 'done'));

  // Генерируем 6 туров Пути РПЛ
  const rplDates = db.cupState2026.rplWeeks || [
    { tue: '2026-07-28', wed: '2026-07-29', thu: '2026-07-30' },
    { tue: '2026-08-11', wed: '2026-08-12', thu: '2026-08-13' },
    { tue: '2026-08-25', wed: '2026-08-26', thu: '2026-08-27' },
    { tue: '2026-09-22', wed: '2026-09-23', thu: '2026-09-24' },
    { tue: '2026-10-20', wed: '2026-10-21', thu: '2026-10-22' },
    { tue: '2026-11-03', wed: '2026-11-04', thu: '2026-11-05' }
  ];

  const groupRoundPairs: any = {
    A: [[[0, 1], [2, 3]], [[0, 2], [3, 1]], [[3, 0], [1, 2]], [[1, 0], [3, 2]], [[2, 0], [1, 3]], [[0, 3], [2, 1]]],
    B: [[[0, 1], [2, 3]], [[0, 2], [3, 1]], [[3, 0], [1, 2]], [[1, 0], [3, 2]], [[2, 0], [1, 3]], [[0, 3], [2, 1]]],
    C: [[[0, 1], [2, 3]], [[0, 2], [3, 1]], [[3, 0], [1, 2]], [[1, 0], [3, 2]], [[2, 0], [1, 3]], [[0, 3], [2, 1]]],
    D: [[[0, 1], [2, 3]], [[0, 2], [3, 1]], [[3, 0], [1, 2]], [[1, 0], [3, 2]], [[2, 0], [1, 3]], [[0, 3], [2, 1]]]
  };

  const newFixtures: any[] = [];
  for (let roundIdx = 0; roundIdx < 6; roundIdx++) {
    const dates = rplDates[roundIdx] || rplDates[rplDates.length - 1];
    const roundMatches: any[] = [];
    for (const gid of groupIds) {
      const pairs = groupRoundPairs[gid][roundIdx];
      const gTeams = rplGroups[gid].teams;
      for (const [hIdx, aIdx] of pairs) {
        roundMatches.push({ home: gTeams[hIdx], away: gTeams[aIdx], gid });
      }
    }
    const slotSchedule = [
      { date: dates.tue, time: '17:30' },
      { date: dates.tue, time: '20:00' },
      { date: dates.wed, time: '15:00' },
      { date: dates.wed, time: '17:30' },
      { date: dates.wed, time: '19:30' },
      { date: dates.wed, time: '20:45' },
      { date: dates.thu, time: '17:30' },
      { date: dates.thu, time: '20:00' }
    ];
    roundMatches.forEach((m: any, slotIdx: number) => {
      const schedule = slotSchedule[slotIdx] || { date: dates.wed, time: '18:00' };
      const fxObj: any = {
        id: uid(),
        season,
        comp: 'cup',
        cupPath: 'rpl_group',
        groupId: m.gid,
        round: roundIdx + 1,
        label: `Путь РПЛ · ${roundIdx + 1}-й тур`,
        date: schedule.date,
        time: schedule.time,
        home: m.home,
        away: m.away,
        status: 'scheduled',
        hg: null,
        ag: null,
        pos: 0
      };
      assignReferee(fxObj);
      newFixtures.push(fxObj);
    });
  }

  db.fixtures.push(...newFixtures);
  save();
  invalidateAgg();
  res.json({ ok: 1, message: 'Групповой этап Пути РПЛ успешно сформирован по итогам жеребьёвки!', count: newFixtures.length });
});

// Утверждение жеребьёвки 1-го раунда Пути Регионов (Медиалига vs 2-я лига)
app.post('/api/admin/draw/apply-cup-regions', admin, (req: any, res) => {
  const { pairs } = req.body;
  if (!Array.isArray(pairs) || !pairs.length) {
    return fail(res, 'Необходимо предоставить пары команд');
  }

  const season = S();
  if (!db.cupState2026) advanceCup();

  // Удаляем старые несыгранные матчи 1-го отборочного раунда
  db.fixtures = db.fixtures.filter((f: any) => !(f.comp === 'cup' && f.cupPath === 'regions_qual' && f.qualRound === 1 && f.status !== 'done'));

  const regDates = db.cupState2026.regWeeks?.[0] || { tue: '2026-07-21', wed: '2026-07-22', thu: '2026-07-23' };
  const newFixtures: any[] = [];
  pairs.forEach(([homeId, awayId]: [string, string], idx: number) => {
    const slot = idx % 3;
    const date = slot === 0 ? regDates.tue : slot === 1 ? regDates.wed : regDates.thu;
    const time = ['14:00', '16:30', '18:30', '20:00'][idx % 4];
    const fxObj: any = {
      id: uid(),
      season,
      comp: 'cup',
      cupPath: 'regions_qual',
      qualRound: 1,
      round: 101,
      label: 'Путь регионов · 1-й отборочный раунд',
      date,
      time,
      home: homeId,
      away: awayId,
      status: 'scheduled',
      hg: null,
      ag: null,
      pos: 0
    };
    assignReferee(fxObj);
    newFixtures.push(fxObj);
  });

  db.fixtures.push(...newFixtures);
  save();
  invalidateAgg();
  res.json({ ok: 1, message: `1-й раунд Пути регионов сформирован (${newFixtures.length} матчей)!` });
});

// Утверждение Кубка Медиалиги
app.post('/api/admin/draw/apply-media-cup', admin, (req: any, res) => {
  const { name = 'Кубок Медиалиги', mode = 'groups', groups, pairs } = req.body;
  const tid = 'mcup_' + uid();
  const compId = 'media_cup';
  const season = S();

  // Удаляем старый кубок медиалиги, если был
  db.tournaments = (db.tournaments || []).filter((t: any) => t.compId !== compId);
  db.fixtures = db.fixtures.filter((f: any) => !(f.comp === compId && f.status !== 'done'));

  const teamIds: string[] = [];
  const newFixtures: any[] = [];

  const baseDate = db.cupState2026?.calBase || '2026-08-01';
  const stadiumList = ['ВТБ Арена (Москва)', 'БСА Лужники (Москва)', 'Сапсан Арена (Москва)', 'Стадион Москвич (Москва)'];

  if (mode === 'groups' && groups) {
    // Групповой этап
    const groupKeys = Object.keys(groups);
    groupKeys.forEach(gKey => {
      teamIds.push(...groups[gKey]);
    });

    groupKeys.forEach((gKey, gIdx) => {
      const gTeams = groups[gKey];
      // Тур 1: 0-1, 2-3; Тур 2: 0-2, 3-1; Тур 3: 0-3, 1-2
      const roundPairs = [
        [[0, 1], [2, 3]],
        [[0, 2], [3, 1]],
        [[0, 3], [1, 2]]
      ];
      roundPairs.forEach((pairsInRound, rIdx) => {
        const matchDate = addDays(baseDate, 14 + rIdx * 7);
        pairsInRound.forEach(([h, a], pIdx) => {
          if (gTeams[h] && gTeams[a]) {
            const fxObj: any = {
              id: uid(),
              season,
              comp: compId,
              groupId: gKey,
              round: rIdx + 1,
              label: `${name} · Группа ${gKey} · ${rIdx + 1}-й тур`,
              date: matchDate,
              time: ['16:00', '18:30', '21:00'][(gIdx + pIdx) % 3],
              home: gTeams[h],
              away: gTeams[a],
              status: 'scheduled',
              hg: null,
              ag: null,
              pos: 0,
              tournamentName: name,
              venue: stadiumList[(gIdx + pIdx) % stadiumList.length]
            };
            assignReferee(fxObj);
            newFixtures.push(fxObj);
          }
        });
      });
    });
  } else if (pairs && Array.isArray(pairs)) {
    // Сетка плей-офф
    pairs.forEach(([h, a]: [string, string], idx: number) => {
      teamIds.push(h, a);
      const matchDate = addDays(baseDate, 20 + Math.floor(idx / 4) * 3);
      const fxObj: any = {
        id: uid(),
        season,
        comp: compId,
        round: 1,
        label: `${name} · 1/4 финала · Пара ${idx + 1}`,
        date: matchDate,
        time: ['15:00', '17:30', '20:00', '21:30'][idx % 4],
        home: h,
        away: a,
        status: 'scheduled',
        hg: null,
        ag: null,
        pos: 0,
        tournamentName: name,
        venue: stadiumList[idx % stadiumList.length]
      };
      assignReferee(fxObj);
      newFixtures.push(fxObj);
    });
  }

  const trn = {
    id: tid,
    compId,
    name: String(name).trim(),
    mode,
    country: 'Россия',
    city: 'Москва',
    startDate: baseDate,
    teamIds: [...new Set(teamIds)],
    createdAt: new Date().toISOString()
  };

  db.tournaments.push(trn);
  db.fixtures.push(...newFixtures);
  save();
  invalidateAgg();

  res.json({ ok: 1, message: `Кубок Медиалиги «${name}» успешно утвержден (${newFixtures.length} матчей)!`, tournament: trn });
});

// Генерация живого комментария ведущего/эксперта для шага жеребьевки
app.post('/api/draw/commentary', async (req: any, res) => {
  const { tournament, step, team: teamObj, targetSlot, assignedGroup, rivalsInSlot = [] } = req.body;
  if (!teamObj) return res.json({ commentator: 'И следующий шар вытянут из лототрона!', guest: '«Продолжаем жеребьевку!»' });

  // Базовый сочный комментарий из базы знаний
  const preset = getPresetCommentary({
    tournament: tournament || 'cup_rpl',
    step: step || 1,
    team: teamObj,
    targetSlot: targetSlot || '',
    assignedGroup: assignedGroup || '',
    rivalsInSlot
  });

  // Если доступен LLM, обогащаем комментарий через ИИ
  if (hasLLM()) {
    try {
      const rivalsText = rivalsInSlot.length ? `Уже в этой группе: ${rivalsInSlot.map((r: any) => r.name).join(', ')}.` : 'Первая команда в этой корзине/группе.';
      const prompt = `Ты — ведущий прямого эфира торжественной жеребьевки ${tournament === 'media_cup' ? 'Кубка Медиалиги' : 'Кубка России'} на Матч ТВ (в стиле Романа Нагучева, Дениса Казанского или ведущих Медиалиги).
Только что достали шар: ${teamObj.name}. Он отправляется в: ${targetSlot} (Группа ${assignedGroup || ''}).
${rivalsText}
Напиши 1-2 сочные, эмоциональные фразы комментария для эфира (с футбольным или медиафутбольным сленгом, интригой, упоминанием дерби или характера команды).
Формат: строго одна-две фразы. Без кавычек.`;

      const aiReply = await llm('Ты — яркий комментатор прямого эфира жеребьевки.', prompt, { json: false, max: 200, temp: 0.85 });
      if (aiReply && aiReply.trim()) {
        return res.json({
          commentator: aiReply.trim(),
          guest: preset.guest,
          dramaLevel: preset.dramaLevel
        });
      }
    } catch (e) {
      // fallback to preset
    }
  }

  res.json(preset);
});

// Тренеры
app.get('/api/coaches', (req, res) => {
  const list = db.teams.map((t: any) => {
    const coach = getCoachForTeam(t.id);
    const synergy = computeCoachSynergy(coach, db.tactics[t.id]);
    return {
      teamId: t.id,
      teamName: t.name,
      comp: t.comp,
      logo: teamLogo(t.id),
      coach,
      synergy
    };
  });
  res.json(list);
});

app.get('/api/coach/:teamId', (req, res) => {
  const t = team(req.params.teamId);
  if (!t) return fail(res, 'Клуб не найден', 404);
  const coach = getCoachForTeam(t.id);
  const synergy = computeCoachSynergy(coach, db.tactics[t.id]);
  res.json({ team: pubTeam(t), coach, synergy });
});

app.post('/api/coach/:teamId', admin, (req, res) => {
  const t = team(req.params.teamId);
  if (!t) return fail(res, 'Клуб не найден', 404);
  const cur = getCoachForTeam(t.id);
  const b = req.body;
  db.coaches ||= {};
  db.coaches[t.id] = {
    ...cur,
    name: b.name ? String(b.name).trim() : cur.name,
    style: b.style && ['bus', 'counter', 'possession', 'attack', 'press'].includes(b.style) ? b.style : cur.style,
    favoriteFormation: b.favoriteFormation || cur.favoriteFormation,
    reputation: Number(b.reputation) || cur.reputation,
    temperament: b.temperament || cur.temperament,
    quote: b.quote || cur.quote
  };
  save();
  res.json({ ok: 1, coach: db.coaches[t.id] });
});

// Сборные и награды (Awards)
app.get('/api/awards/round', (req, res) => {
  const comp = String(req.query.comp || 'rpl');
  const compFx = seasonFx().filter((f: any) => f.comp === comp && f.status === 'done');
  const rounds = [...new Set(compFx.map((f: any) => roundLabel(f)))];
  const requestedRound = String(req.query.round || rounds[rounds.length - 1] || '1-й тур');

  const matchesMap: Record<string, any> = {};
  for (const f of compFx) {
    const m = getMatch(f.id);
    if (m) matchesMap[f.id] = m;
  }
  const teamsMap = Object.fromEntries(db.teams.map((t: any) => [t.id, pubTeam(t)]));

  const teamOfRound = buildTeamOfRound(requestedRound, comp, compFx, matchesMap, teamsMap);
  res.json({
    comp,
    availableRounds: rounds,
    selectedRound: requestedRound,
    teamOfRound
  });
});

app.get('/api/awards/month', (req, res) => {
  const comp = String(req.query.comp || 'rpl');
  const compFx = seasonFx().filter((f: any) => f.comp === comp && f.status === 'done');
  const months = [...new Set(compFx.map((f: any) => (f.date || '').slice(0, 7)).filter(Boolean))].sort();
  const requestedMonth = String(req.query.month || months[months.length - 1] || '2026-08');

  const matchesMap: Record<string, any> = {};
  for (const f of compFx) {
    const m = getMatch(f.id);
    if (m) matchesMap[f.id] = m;
  }
  const teamsMap = Object.fromEntries(db.teams.map((t: any) => [t.id, pubTeam(t)]));

  const teamOfMonth = buildTeamOfMonth(requestedMonth, comp, compFx, matchesMap, teamsMap);
  res.json({
    comp,
    availableMonths: months,
    selectedMonth: requestedMonth,
    teamOfMonth
  });
});

app.get('/api/awards/season', (req, res) => {
  const comp = String(req.query.comp || 'rpl');
  const A = agg();
  const P = Object.values<any>(A.P).filter(x => x.comp === comp);
  const rows = table(comp);

  const topScorer = [...P].sort((a, b) => b.g - a.g || b.min - a.min)[0] || null;
  const topAssister = [...P].sort((a, b) => b.a - a.a || b.min - a.min)[0] || null;
  const bestGk = [...P].filter(p => p.cs > 0 || p.sv > 0).sort((a, b) => b.cs - a.cs || b.sv - a.sv)[0] || null;

  const championTeam = rows[0] ? team(rows[0].id) : null;
  const coachOfSeason = championTeam ? {
    coach: getCoachForTeam(championTeam.id),
    teamName: championTeam.name,
    teamLogo: teamLogo(championTeam.id),
    title: 'Тренер года',
    reason: `Привёл команду «${championTeam.name}» к чемпионскому титулу`
  } : null;

  const matchesMap: Record<string, any> = {};
  for (const f of seasonFx().filter((f: any) => f.comp === comp && f.status === 'done')) {
    const m = getMatch(f.id);
    if (m) matchesMap[f.id] = m;
  }
  const teamsMap = Object.fromEntries(db.teams.map((t: any) => [t.id, pubTeam(t)]));
  const allMonths: string[] = [...new Set<string>(seasonFx().map((f: any) => String(f.date || '').slice(0, 7)).filter(Boolean))].sort();
  const latestMonth: string = allMonths[allMonths.length - 1] || '2026-08';
  const teamOfSeason = buildTeamOfMonth(latestMonth, comp, seasonFx(), matchesMap, teamsMap);

  res.json({
    comp,
    season: S(),
    topScorer: topScorer ? { ...topScorer, team: tn(topScorer.t), logo: teamLogo(topScorer.t) } : null,
    topAssister: topAssister ? { ...topAssister, team: tn(topAssister.t), logo: teamLogo(topAssister.t) } : null,
    bestGk: bestGk ? { ...bestGk, team: tn(bestGk.t), logo: teamLogo(bestGk.t) } : null,
    coachOfSeason,
    teamOfSeason
  });
});

