app.post('/api/club/squad/nation', needClub, (req: any, res) => {
  const p = player(req.body.playerId);
  if (!p) return fail(res, 'Игрок не найден');
  const inSquad = squadOf(req.tid).some((x: any) => x.id === p.id);
  if (!inSquad && req.me?.role !== 'admin') return fail(res, 'Менять страну можно только у игроков вашей заявки');
  const nat = cleanNation(req.body.nation);
  if (!nat) return fail(res, 'Укажите страну');
  const prev = p.nation;
  const wasLeg = isLegionnaire(p);
  p.nation = nat;
  // если игрок стал легионером — проверяем лимит заявки РПЛ
  const tm = team(req.tid);
  if (tm && tm.comp === 'rpl' && inSquad && !wasLeg && isLegionnaire(p)) {
    const limit = getRplLegionLimit(S());
    const legions = squadOf(req.tid).filter(isLegionnaire).length;
    if (legions > limit.inSquad) {
      p.nation = prev;
      return fail(res, `С этой страной игрок станет легионером, а лимит легионеров в заявке РПЛ — ${limit.inSquad} (лимит ${limit.label}). Сначала освободите место.`);
    }
  }
  p.updatedAt = new Date().toISOString();
  save();
  res.json({ ok: 1, nation: p.nation, legionStatus: getLegionnaireStatus(p) });
});

app.post('/api/club/squad/remove', needClub, (req: any, res) => {
  const cur = squadOf(req.tid).filter((p: any) => p.id !== req.body.playerId);
  db.squads[req.tid] = cur.map((p: any) => p.id);
  const p = player(req.body.playerId);
  if (p && p.teamId === req.tid) p.teamId = null;
  save();
  res.json({ ok: 1 });
});

app.post('/api/club/squad/submit', needClub, (req: any, res) => {
  db.squads[req.tid] = squadOf(req.tid).map((p: any) => p.id);
  save();
  res.json({ ok: 1 });
});

app.post('/api/club/lineup', needClub, (req: any, res) => {
  const f = fx(req.body.fid);
  if (!f || (f.home !== req.tid && f.away !== req.tid)) return fail(res, 'Это не матч вашего клуба');
  if (f.status !== 'scheduled') return fail(res, 'Матч уже начался — состав закрыт');
  const ownIds = new Set(squadOf(req.tid).map((p: any) => p.id));
  // можно заявить игроков из заявок дублей/молодёжки/основы своего клуба — разово, только на этот матч
  const loanIds = new Set(loanPoolFor(req.tid, f).map((x: any) => x.p.id));
  const sq = new Set([...ownIds, ...loanIds]);
  const st = (req.body.starters || []).filter((id: string) => sq.has(id));
  if (new Set(st).size !== st.length) return fail(res, 'Игрок указан дважды');
  if (st.length !== 11) return fail(res, 'В старте должно быть ровно 11 игроков');
  if (!st.some((id: string) => player(id)?.pos === 'ВР')) return fail(res, 'В старте нужен вратарь');
  const bad = st.map(player).filter((p: any) => !isAvail(p, f.date));
  if (bad.length) return fail(res, `Недоступны: ${bad.map((p: any) => p.name).join(', ')}`);
  const benchIds0 = (req.body.bench || []).filter((id: string) => sq.has(id) && !st.includes(id)).slice(0, 12);
  for (const id of [...st, ...benchIds0]) {
    const w = loanBusyWith(id, f.date, req.tid);
    if (w) return fail(res, `${player(id)?.name}: уже заявлен на матч команды «${w}» в этот же день`);
    if (!ownIds.has(id) && !isAvail(player(id), f.date)) return fail(res, `${player(id)?.name} недоступен`);
  }

  // Лимит на легионеров на поле в РПЛ (12+7 в 2026/27, 11+6 в 2027/28, 10+5 в 2028/29)
  if (f.comp === 'rpl') {
    const limit = getRplLegionLimit(S());
    const legionStarters = st.map(player).filter(isLegionnaire);
    if (legionStarters.length > limit.onPitch) {
      return fail(res, `Превышен лимит легионеров на поле в РПЛ: в стартовом составе ${legionStarters.length} легионеров, разрешено максимум ${limit.onPitch} (лимит ${limit.label} на сезон ${S()})`);
    }
  }

  const fm = /^\d(-\d){1,3}$/.test(req.body.formation || '') ? req.body.formation : '4-3-3';
  const bench = benchIds0;
  const L = {
    formation: fm,
    starters: st,
    bench,
    speech: String(req.body.speech || '').slice(0, 4000),
    training: String(req.body.training || '').slice(0, 4000),
    at: Date.now()
  };
  db.lineups[f.id + ':' + req.tid] = L;
  // «по умолчанию» на другие матчи переносим только свой состав — арендованные на 1 игру не тянутся дальше
  db.tactics[req.tid] = { ...L, starters: L.starters.filter((id: string) => ownIds.has(id)), bench: L.bench.filter((id: string) => ownIds.has(id)) };
  save();
  res.json({ ok: 1 });
});

