app.post('/api/admin/settings', admin, (req, res) => {
  const b = req.body, s = db.settings;
  for (const k of ['season', 'siteUrl']) if (typeof b[k] === 'string') s[k] = b[k].trim();
  if (typeof b.tgChat === 'string') {
    s.tgChat = normalizeTgChat(b.tgChat);
    tgCooldownUntil = 0;
    tgLastStatus = { ok: true };
  }
  if (typeof b.tgToken === 'string' && !b.tgToken.includes('•')) {
    s.tgToken = b.tgToken.trim();
    tgCooldownUntil = 0;
    tgLastStatus = { ok: true };
  }
  for (const k of ['secPerMin', 'breakSec', 'squadMax', 'maxAiCalls', 'aiParallel']) if (b[k] !== undefined && +b[k] > 0) s[k] = +b[k];
  if (b.aiLeadSec !== undefined && +b.aiLeadSec >= 0) s.aiLeadSec = Math.min(900, +b.aiLeadSec);
  if (b.chunks !== undefined) s.chunks = +b.chunks === 6 ? 6 : 2;
  if (b.auto !== undefined) s.auto = !!b.auto;
  if (b.techDefeat !== undefined) s.techDefeat = !!b.techDefeat;
  if (b.grounding !== undefined) s.grounding = !!b.grounding;
  if (typeof b.systemPrompt === 'string') s.systemPrompt = b.systemPrompt.trim() === SYS_DEFAULT.trim() ? '' : b.systemPrompt;
  for (const k of ['gemini', 'groq', 'openrouter']) {
    if (typeof b.keys?.[k] === 'string' && b.keys[k].trim()) s.keys[k] = b.keys[k].trim();
    if (b.keys?.[k] === '') delete s.keys[k];
    if (typeof b.models?.[k] === 'string') {
      if (b.models[k].trim()) s.models[k] = b.models[k].trim();
      else delete s.models[k];
    }
  }
  save();
  res.json({ ok: 1 });
});

app.post('/api/admin/telegram/test', admin, async (req: any, res) => {
  const token = (typeof req.body?.tgToken === 'string' && !req.body.tgToken.includes('•') && req.body.tgToken.trim())
    ? req.body.tgToken.trim()
    : tgToken();
  const rawChat = (typeof req.body?.tgChat === 'string' && req.body.tgChat.trim())
    ? req.body.tgChat.trim()
    : tgChat();
  const chat = normalizeTgChat(rawChat);

  if (!token) {
    return fail(res, 'Токен бота не указан. Введите токен Telegram-бота (например, 123456:ABC... от @BotFather)');
  }
  if (!chat) {
    return fail(res, 'Имя или ID канала не указаны. Введите @имя_канала или числовой ID');
  }

  // Сбрасываем кулдаун при ручном тестировании
  tgCooldownUntil = 0;

  try {
    const url = `https://api.telegram.org/bot${token}/sendMessage`;
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        chat_id: chat,
        text: `🏟 <b>Вирт РПЛ</b>: Проверка связи с Telegram-каналом прошла успешно!\n\nВсе матчи и события транслируются в канал в реальном времени.`,
        parse_mode: 'HTML',
        disable_web_page_preview: true
      })
    });
    const data: any = await resp.json().catch(() => ({}));
    if (!resp.ok || !data.ok) {
      const desc = data.description || `HTTP ${resp.status}`;
      let hint = '';
      if (resp.status === 403 || desc.includes('not a member') || desc.includes('Forbidden') || desc.includes('administrator')) {
        hint = ` Бот @RPLVIRT_bot не добавлен в администраторы канала ${chat}. Перейдите в Telegram, откройте канал ${chat} → Управление каналом → Администраторы → Добавить администратора → найдите @RPLVIRT_bot и выдайте право «Публикация сообщений».`;
        tgLastStatus = { ok: false, status: 403, error: desc, at: new Date().toISOString() };
      } else if (desc.includes('chat not found')) {
        hint = ' Проверьте правильность названия канала и обязательно добавьте бота в администраторы канала с правом публикации сообщений.';
        tgLastStatus = { ok: false, status: 400, error: desc, at: new Date().toISOString() };
      } else if (desc.includes('Unauthorized') || desc.includes('Not Found')) {
        hint = ' Проверьте правильность токена бота Telegram.';
        tgLastStatus = { ok: false, status: 401, error: desc, at: new Date().toISOString() };
      } else if (desc.includes("can't parse entities")) {
        hint = ' Ошибка парсинга разметки.';
      }
      return fail(res, `Ошибка Telegram: ${desc}.${hint}`);
    }
    tgLastStatus = { ok: true, at: new Date().toISOString() };
    return res.json({ ok: 1, message: `Тестовое сообщение успешно отправлено в Telegram-канал ${chat}!` });
  } catch (err: any) {
    return fail(res, `Сетевая ошибка при отправке в Telegram: ${err.message}`);
  }
});

app.post('/api/admin/season', admin, (req, res) => {
  let start = String(req.body.start || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start)) return fail(res, 'Укажите дату старта (ГГГГ-ММ-ДД)');
  if (!/^\d{4}-07-\d{2}$/.test(start)) return fail(res, 'По игровому времени сезон можно начинать только в июле. Реальное время можно выбрать любое.');
  const name = String(req.body.name || S()).trim();
  if (seasonFx().length && db.settings.season === name && !req.body.force) {
    return fail(res, 'Для этого сезона расписание уже есть. Измените название сезона или подтвердите пересоздание.');
  }
  if (db.settings.season === name) db.fixtures = db.fixtures.filter((f: any) => f.season !== name);
  db.settings.manualDraw = false;
  const realStartBody = String(req.body.realStart || '');
  genSeason(start, name, { realStart: /^\d{4}-\d{2}-\d{2}$/.test(realStartBody) ? realStartBody : start });
  save();
  res.json({ ok: 1, fixtures: seasonFx().length, realStartDate: db.settings.realStartDate });
});

