/* ───────── тренерский штаб: клуб подаёт краткую информацию, админ делает портрет через ИИ ───────── */
const cleanStr = (v: any, n: number) => String(v ?? '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, n);
/* ── должности: стандартные (STAFF_ROLES) + свои, которые клуб создаёт сам ── */
const MAX_CUSTOM_ROLES = 12;
function customRolesOf(tid: string): any[] {
  return (db.staffRoles || []).filter((r: any) => r.teamId === tid);
}
/** описание должности для клуба: стандартная или собственная */
function roleMetaFor(tid: string, role: string): any | null {
  if ((STAFF_ROLES as any)[role]) return (STAFF_ROLES as any)[role];
  const c = customRolesOf(tid).find((r: any) => r.id === role);
  return c ? { title: c.title, short: c.title, desc: c.desc || '', icon: c.icon || '🧩', custom: true } : null;
}
const roleValidFor = (tid: string, role: string) => STAFF_ROLE_LIST.includes(role) || customRolesOf(tid).some((r: any) => r.id === role);
const isRoleRequired = (role: string) => REQUIRED_STAFF_ROLES.includes(role);

function staffSlots(tid: string) {
  const staff = getStaffForTeam(tid);
  const rolesList = [...STAFF_ROLE_LIST, ...customRolesOf(tid).map((r: any) => r.id)];
  return rolesList.map(role => {
    const meta: any = roleMetaFor(tid, role) || {};
    const m = staff.find((x: any) => x.role === role) || null;
    return {
      role, title: meta.title || role, icon: meta.icon || '', desc: meta.desc || '',
      required: isRoleRequired(role),
      custom: !!meta.custom,
      member: m ? { id: m.id, name: m.name, age: m.age, nationality: m.nationality, brief: m.brief || '', pending: !!m.pending } : null
    };
  });
}
// клуб назначает/заменяет специалиста: краткая информация → портрет сделает админ
app.post('/api/club/staff/set', needClub, (req: any, res) => {
  const role = String(req.body.role || '');
  if (!roleValidFor(req.tid, role)) return fail(res, 'Неизвестная должность');
  const name = cleanStr(req.body.name, 80);
  if (name.length < 3) return fail(res, 'Укажите ФИО специалиста');
  const brief = cleanStr(req.body.brief, 600);
  const ageN = Number(req.body.age);
  const nat = cleanNation(req.body.nationality);
  const tm = team(req.tid);
  const meta: any = roleMetaFor(req.tid, role);
  if (!Array.isArray(db.staff)) db.staff = [];
  const prev = db.staff.find((x: any) => x.teamId === req.tid && x.role === role);
  db.staff = db.staff.filter((x: any) => !(x.teamId === req.tid && x.role === role));
  const member: any = {
    id: 'staff_' + uid(), name, role, roleTitle: meta.title,
    teamId: req.tid, teamName: tm ? tm.name : '',
    age: ageN >= 25 && ageN <= 85 ? Math.round(ageN) : undefined,
    nationality: nat || '', specialty: '', bio: '', brief,
    pending: true, verified: false,
    favoriteFormation: role === 'head' ? '4-3-3' : undefined,
    style: role === 'head' ? 'possession' : undefined,
    styleTitle: role === 'head' ? 'Сбалансированный стиль' : undefined,
    updatedAt: new Date().toISOString()
  };
  db.staff.push(member);
  // заменённый специалист больше не в клубе — его заявки на покупку закрываем
  if (prev) cancelStaffOffersFor(prev.id, 'Специалист больше не работает в клубе');
  save();
  try { tg(`🧑‍🏫 <b>${esc(tm?.name)}</b>: ${prev ? 'замена' : 'назначение'} — ${esc(meta.title)}: <b>${esc(name)}</b>${prev ? ` (вместо ${esc(prev.name)})` : ''}. Ожидает портрета ИИ.`); } catch { }
  res.json({ ok: 1, member, staffSlots: staffSlots(req.tid) });
});
app.post('/api/club/staff/remove', needClub, (req: any, res) => {
  const role = String(req.body.role || '');
  if (!roleValidFor(req.tid, role)) return fail(res, 'Неизвестная должность');
  if (isRoleRequired(role)) return fail(res, 'Обязательную должность нельзя оставить пустой — назначьте замену');
  const gone = (db.staff || []).filter((x: any) => x.teamId === req.tid && x.role === role);
  db.staff = (db.staff || []).filter((x: any) => !(x.teamId === req.tid && x.role === role));
  gone.forEach((g: any) => cancelStaffOffersFor(g.id, 'Специалист больше не работает в клубе'));
  save();
  res.json({ ok: 1, staffSlots: staffSlots(req.tid) });
});

/* ── своя должность клуба (например «Скаут», «Психолог», «Тренер по видеоаналитике») ── */
app.post('/api/club/staff/role/create', needClub, (req: any, res) => {
  const title = cleanStr(req.body.title, 50);
  if (title.length < 3) return fail(res, 'Название должности — от 3 знаков');
  const desc = cleanStr(req.body.desc, 200);
  const icon = String(req.body.icon || '').trim().slice(0, 4) || '🧩';
  const mine = customRolesOf(req.tid);
  if (mine.length >= MAX_CUSTOM_ROLES) return fail(res, `Можно создать не больше ${MAX_CUSTOM_ROLES} своих должностей`);
  const low = title.toLowerCase();
  const dup = [...Object.values(STAFF_ROLES as any).map((r: any) => String(r.title).toLowerCase()), ...mine.map((r: any) => r.title.toLowerCase())];
  if (dup.includes(low)) return fail(res, 'Такая должность в клубе уже есть');
  const role = { id: 'c_' + uid(), teamId: req.tid, title, desc, icon, createdAt: new Date().toISOString() };
  db.staffRoles.push(role);
  save();
  res.json({ ok: 1, role, staffSlots: staffSlots(req.tid) });
});
app.post('/api/club/staff/role/delete', needClub, (req: any, res) => {
  const role = String(req.body.role || '');
  const r = customRolesOf(req.tid).find((x: any) => x.id === role);
  if (!r) return fail(res, 'Своя должность не найдена (стандартные удалить нельзя)');
  const gone = (db.staff || []).filter((x: any) => x.teamId === req.tid && x.role === role);
  db.staff = (db.staff || []).filter((x: any) => !(x.teamId === req.tid && x.role === role));
  gone.forEach((g: any) => cancelStaffOffersFor(g.id, 'Должность в клубе упразднена'));
  db.staffRoles = db.staffRoles.filter((x: any) => x.id !== role);
  save();
  res.json({ ok: 1, staffSlots: staffSlots(req.tid) });
});

/* ───────── покупка тренера и специалистов штаба у других клубов ─────────
   Заявка → согласие клуба-продавца (если у клуба есть владелец) → одобрение админа → переход со сделкой по бюджету. */
const offerFeeEuros = (o: any) => Math.round((Number(o.feeAmount) || 0) * 1_000_000);

function cancelStaffOffersFor(staffId: string, reason: string) {
  for (const o of (db.staffOffers || [])) {
    if (o.staffId === staffId && o.status === 'pending') { o.status = 'rejected'; o.rejectReason = reason; }
  }
}
function staffOfferView(o: any) {
  const m = (db.staff || []).find((x: any) => x.id === o.staffId);
  const sellerHas = (db.staff || []).filter((x: any) => x.teamId === o.from && x.role === o.role).length;
  return {
    ...o,
    fromName: tn(o.from) || o.fromName, toName: tn(o.to) || o.toName,
    fromLogo: teamLogo(o.from), toLogo: teamLogo(o.to),
    // после продажи у продавца может опустеть обязательная должность — без неё матч не допускается
    leavesVacancy: o.status === 'pending' && !!m && m.teamId === o.from && isRoleRequired(o.role) && sellerHas <= 1,
    replaces: o.status === 'pending' ? (db.staff || []).filter((x: any) => x.teamId === o.to && x.role === o.targetRole).map((x: any) => x.name) : (o.replacedNames || [])
  };
}
function staffOffersFor(tid: string) {
  const all = db.staffOffers || [];
  return {
    incoming: all.filter((o: any) => o.from === tid && o.status === 'pending').map(staffOfferView),
    outgoing: all.filter((o: any) => o.to === tid && o.status === 'pending').map(staffOfferView),
    history: all.filter((o: any) => (o.from === tid || o.to === tid) && o.status !== 'pending').slice(0, 15).map(staffOfferView)
  };
}

// каталог специалистов других клубов, доступных для заявки
app.get('/api/club/staff/market', needClub, (req: any, res) => {
  const role = String(req.query.role || '');
  const q = String(req.query.q || '').trim().toLowerCase();
  const club = String(req.query.club || '');
  const mineOffers = new Set((db.staffOffers || []).filter((o: any) => o.to === req.tid && o.status === 'pending').map((o: any) => o.staffId));
  let list = (db.staff || []).filter((m: any) => m.teamId && m.teamId !== req.tid && team(m.teamId));
  if (role) list = list.filter((m: any) => m.role === role);
  if (club) list = list.filter((m: any) => m.teamId === club);
  if (q) list = list.filter((m: any) => (m.name || '').toLowerCase().includes(q) || tn(m.teamId).toLowerCase().includes(q));
  const total = list.length;
  list = list.sort((a: any, b: any) => ((b.reputation || 0) - (a.reputation || 0)) || String(a.name).localeCompare(String(b.name), 'ru')).slice(0, 120);
  res.json({
    total,
    roles: STAFF_ROLE_LIST.map(r => ({ role: r, title: (STAFF_ROLES as any)[r]?.title || r })),
    myRoles: staffSlots(req.tid).map((s: any) => ({ role: s.role, title: s.title, custom: s.custom })),
    budget: team(req.tid)?.budget || 0,
    members: list.map((m: any) => ({
      id: m.id, name: m.name, role: m.role, roleTitle: m.roleTitle || roleMetaFor(m.teamId, m.role)?.title || m.role,
      custom: String(m.role).startsWith('c_'),
      age: m.age, nationality: m.nationality, specialty: m.specialty || '', reputation: m.reputation, styleTitle: m.styleTitle || '',
      teamId: m.teamId, teamName: tn(m.teamId), teamLogo: teamLogo(m.teamId),
      offered: mineOffers.has(m.id)
    }))
  });
});

app.get('/api/club/staff/offers', needClub, (req: any, res) => res.json(staffOffersFor(req.tid)));

// клуб подаёт заявку на покупку специалиста
app.post('/api/club/staff/offer', needClub, (req: any, res) => {
  const m = (db.staff || []).find((x: any) => x.id === String(req.body.staffId || ''));
  if (!m || !m.teamId) return fail(res, 'Специалист не найден');
  if (m.teamId === req.tid) return fail(res, 'Это специалист вашего клуба');
  const buyer = team(req.tid), seller = team(m.teamId);
  if (!buyer || !seller) return fail(res, 'Клуб не найден');
  if ((db.staffOffers || []).some((o: any) => o.status === 'pending' && o.staffId === m.id && o.to === req.tid)) {
    return fail(res, 'Вы уже подали заявку на этого специалиста — дождитесь решения');
  }
  const feeStr = String(req.body.fee || '€1.0M').trim().slice(0, 30);
  const feeAmount = parseFeeAmount(feeStr);
  if (!(feeAmount >= 0)) return fail(res, 'Не удалось разобрать сумму компенсации (пример: €1.5M)');
  if (offerFeeEuros({ feeAmount }) > (buyer.budget || 0)) return fail(res, 'Недостаточно средств в бюджете клуба для такой компенсации');

  // на какую должность в вашем клубе: по умолчанию та же; для чужой «своей» должности создадим такую же у вас
  let targetRole = String(req.body.targetRole || '').trim();
  const sellerCustom = String(m.role).startsWith('c_');
  if (!targetRole) targetRole = sellerCustom ? 'copy' : m.role;
  if (targetRole !== 'copy' && !roleValidFor(req.tid, targetRole)) return fail(res, 'Такой должности в вашем клубе нет — создайте её на вкладке «Штаб»');
  // как в трансферах игроков: между клубами РПЛ нужно согласие продавца, в остальных случаях решает админ
  const needClub = seller.comp === 'rpl' && buyer.comp === 'rpl';
  const o: any = {
    id: 'sof_' + uid(),
    staffId: m.id, staffName: m.name, role: m.role,
    roleTitle: m.roleTitle || roleMetaFor(m.teamId, m.role)?.title || m.role,
    targetRole, from: m.teamId, fromName: seller.name, to: req.tid, toName: buyer.name,
    fee: feeStr, feeAmount, note: cleanStr(req.body.note, 300),
    status: 'pending', needClub,
    clubApproval: needClub ? 'pending' : 'not_required', adminApproval: 'pending',
    initiator: req.tid, date: new Date().toISOString().slice(0, 10), at: Date.now()
  };
  db.staffOffers.unshift(o);
  save();
  try { tg(`🧑‍🏫 Заявка на специалиста: <b>${esc(buyer.name)}</b> хочет <b>${esc(m.name)}</b> (${esc(o.roleTitle)}) из «${esc(seller.name)}» за ${esc(feeStr)}.`); } catch { }
  res.json({ ok: 1, offer: staffOfferView(o), message: needClub
    ? `Заявка на ${m.name} отправлена клубу «${seller.name}» и администратору лиги.`
    : `Заявка на ${m.name} отправлена администратору лиги.` });
});

/** исполнить сделку, если получены нужные согласия */
function executeStaffOfferIfApproved(o: any): { executed: boolean; error?: string } {
  if (o.status === 'approved') return { executed: true };
  if (o.status !== 'pending') return { executed: false };
  const clubOk = !o.needClub || o.clubApproval === 'approved';
  if (!(clubOk && o.adminApproval === 'approved')) return { executed: false };

  const reject = (why: string) => { o.status = 'rejected'; o.rejectReason = why; return { executed: false, error: why }; };
  const m = (db.staff || []).find((x: any) => x.id === o.staffId);
  if (!m || m.teamId !== o.from) return reject('Специалист уже не работает в этом клубе');
  const buyer = team(o.to), seller = team(o.from);
  if (!buyer || !seller) return reject('Клуб не найден');
  const euros = offerFeeEuros(o);
  if (euros > (buyer.budget || 0)) return reject('У клуба-покупателя не хватает средств на компенсацию');

  // целевая должность
  let targetRole = o.targetRole;
  if (targetRole === 'copy') {
    const src = (db.staffRoles || []).find((r: any) => r.id === o.role);
    const have = customRolesOf(o.to).find((r: any) => r.title.toLowerCase() === String(src?.title || o.roleTitle).toLowerCase());
    if (have) targetRole = have.id;
    else {
      const nr = { id: 'c_' + uid(), teamId: o.to, title: src?.title || o.roleTitle, desc: src?.desc || '', icon: src?.icon || '🧩', createdAt: new Date().toISOString() };
      db.staffRoles.push(nr); targetRole = nr.id;
    }
  }
  if (!roleValidFor(o.to, targetRole)) return reject('Должность в клубе-покупателе больше не существует');
  const meta: any = roleMetaFor(o.to, targetRole);

  // действующий специалист на этой должности у покупателя уходит
  const out = (db.staff || []).filter((x: any) => x.teamId === o.to && x.role === targetRole);
  o.replacedNames = out.map((x: any) => x.name);
  out.forEach((x: any) => cancelStaffOffersFor(x.id, 'Специалист больше не работает в клубе'));
  db.staff = db.staff.filter((x: any) => !(x.teamId === o.to && x.role === targetRole));

  m.teamId = o.to; m.teamName = buyer.name; m.role = targetRole; m.roleTitle = meta.title;
  if (targetRole === 'head') {
    m.style ||= 'possession'; m.styleTitle ||= 'Сбалансированный стиль'; m.favoriteFormation ||= '4-3-3';
  }
  m.updatedAt = new Date().toISOString();

  if (euros > 0) {
    if (!Array.isArray(db.budgetHistory)) db.budgetHistory = [];
    const pb = buyer.budget || 0; buyer.budget = pb - euros;
    db.budgetHistory.push({ id: uid(), teamId: buyer.id, teamName: buyer.name, amount: -euros, prevBudget: pb, newBudget: buyer.budget,
      type: 'staff_buy', typeLabel: 'Покупка тренера/специалиста', description: `Штаб: ${m.name} (${meta.title}) из «${seller.name}» (-€${euros.toLocaleString('ru-RU')})`, date: new Date().toISOString() });
    const ps = seller.budget || 0; seller.budget = ps + euros;
    db.budgetHistory.push({ id: uid(), teamId: seller.id, teamName: seller.name, amount: euros, prevBudget: ps, newBudget: seller.budget,
      type: 'staff_sell', typeLabel: 'Продажа тренера/специалиста', description: `Штаб: ${m.name} ушёл в «${buyer.name}» (+€${euros.toLocaleString('ru-RU')})`, date: new Date().toISOString() });
  }
  for (const other of db.staffOffers) {
    if (other.id !== o.id && other.staffId === o.staffId && other.status === 'pending') {
      other.status = 'rejected'; other.rejectReason = `Специалист перешёл в «${buyer.name}»`;
    }
  }
  o.status = 'approved'; o.executedAt = new Date().toISOString();
  try { tg(`✅ Штаб: <b>${esc(m.name)}</b> (${esc(meta.title)}) переходит из «${esc(seller.name)}» в «${esc(buyer.name)}» (${esc(o.fee)}).`); } catch { }
  return { executed: true };
}

// ответ клуба: продавец одобряет/отклоняет, покупатель может отозвать
app.post('/api/club/staff/offer/respond', needClub, (req: any, res) => {
  const { offerId, action } = req.body;
  const o = (db.staffOffers || []).find((x: any) => x.id === offerId);
  if (!o || o.status !== 'pending') return fail(res, 'Заявка не найдена или уже закрыта');
  if (action === 'cancel') {
    if (o.to !== req.tid) return fail(res, 'Отозвать заявку может только её автор');
    o.status = 'cancelled'; o.rejectReason = 'Отозвана клубом';
    save();
    return res.json({ ok: 1, cancelled: true, message: 'Заявка отозвана' });
  }
  if (o.from !== req.tid) return fail(res, 'Эта заявка адресована не вашему клубу');
  if (action === 'approve') {
    o.clubApproval = 'approved'; o.clubRespondedAt = new Date().toISOString();
    const r = executeStaffOfferIfApproved(o);
    save();
    return res.json({ ok: 1, approved: true, executed: r.executed, message: r.executed
      ? 'Сделка завершена — специалист перешёл в другой клуб. Не забудьте назначить замену.'
      : r.error ? `Не удалось завершить: ${r.error}` : 'Вы дали согласие. Ожидается решение администратора лиги.' });
  }
  o.clubApproval = 'rejected'; o.status = 'rejected'; o.rejectReason = `Отклонено клубом «${tn(req.tid)}»`;
  save();
  res.json({ ok: 1, rejected: true, message: `Вы отклонили заявку на ${o.staffName}.` });
});

// админ: все заявки и решение
app.get('/api/admin/staff-offers', admin, (req, res) => {
  const all = (db.staffOffers || []).map(staffOfferView);
  res.json({ pending: all.filter((o: any) => o.status === 'pending'), history: all.filter((o: any) => o.status !== 'pending').slice(0, 30) });
});
app.post('/api/admin/staff-offer/respond', admin, (req, res) => {
  const { offerId, action, force } = req.body;
  const o = (db.staffOffers || []).find((x: any) => x.id === offerId);
  if (!o || o.status !== 'pending') return fail(res, 'Заявка не найдена или уже закрыта');
  if (action === 'approve') {
    o.adminApproval = 'approved';
    if (force) o.clubApproval = 'approved';
    const r = executeStaffOfferIfApproved(o);
    save();
    return res.json({ ok: 1, approved: true, executed: r.executed, offer: staffOfferView(o), message: r.executed
      ? 'Сделка завершена'
      : r.error ? `Не удалось завершить: ${r.error}` : 'Одобрено. Ждём согласия клуба-продавца.' });
  }
  o.adminApproval = 'rejected'; o.status = 'rejected'; o.rejectReason = 'Отклонено администратором';
  save();
  res.json({ ok: 1, rejected: true, message: 'Заявка отклонена' });
});

const STAFF_SYS = `Ты — футбольный аналитик для симулятора. По ФИО, должности и краткой информации от клуба верни портрет специалиста тренерского штаба в JSON. Если это реальный известный специалист — используй только достоверные факты. Если такого человека не знаешь — не выдумывай регалии, клубы и титулы: опирайся только на краткую информацию клуба и составь нейтральный портрет (found=false). Не пиши о личной жизни, здоровье, скандалах. Формат: {"found":true,"name":"ФИО по-русски","age":число,"nationality":"страна","specialty":"1 предложение о специализации","bio":"2-4 предложения: карьера, опыт, подход к работе","style":"только для главного тренера, одно из: possession, press, counter, attack, bus","styleTitle":"короткое название стиля (только для главного тренера)","favoriteFormation":"например 4-3-3 (только для главного тренера)","reputation":число 50-95 (только для главного тренера),"temperament":"1-3 слова (только для главного тренера)","quote":"фирменная фраза в «ёлочках» (только для главного тренера)"}`;
function applyStaffPortrait(m: any, c: any): boolean {
  if (!c || typeof c !== 'object') return false;
  const known = c.found !== false;
  if (known && c.name && cleanStr(c.name, 80).length >= 3) m.name = cleanStr(c.name, 80);
  const a = Number(c.age);
  if (known && a >= 25 && a <= 85) m.age = Math.round(a); else if (!m.age) m.age = 45;
  if (known && c.nationality) m.nationality = cleanStr(c.nationality, 40); else if (!m.nationality) m.nationality = 'Россия';
  m.specialty = cleanStr(c.specialty, 300) || m.specialty || ((STAFF_ROLES as any)[m.role]?.desc || '');
  m.bio = cleanStr(c.bio, 1200) || m.brief || m.bio || '';
  if (m.role === 'head') {
    if (['possession', 'press', 'counter', 'attack', 'bus'].includes(c.style)) m.style = c.style;
    if (c.styleTitle) m.styleTitle = cleanStr(c.styleTitle, 80);
    if (/^\d(-\d){1,3}$/.test(String(c.favoriteFormation || '').trim())) m.favoriteFormation = String(c.favoriteFormation).trim();
    const r = Number(c.reputation); if (r >= 50 && r <= 99) m.reputation = Math.round(r);
    if (c.temperament) m.temperament = cleanStr(c.temperament, 60);
    if (c.quote) m.quote = cleanStr(c.quote, 200);
  }
  m.pending = false;
  m.verified = known;
  m.portraitAt = new Date().toISOString();
  m.updatedAt = m.portraitAt;
  return true;
}
async function staffPortrait(m: any): Promise<boolean> {
  const tm = team(m.teamId);
  const meta: any = (STAFF_ROLES as any)[m.role] || {};
  const prompt = `Специалист: ${m.name}. Должность: ${meta.title || m.role}.${tm ? ` Клуб в симуляторе: ${tm.name}.` : ''}${m.nationality ? ` Гражданство: ${m.nationality}.` : ''}${m.age ? ` Возраст: ${m.age}.` : ''}\nКраткая информация от клуба: ${m.brief || '— не указана'}.\nСоставь портрет.`;
  const grounded = provList()[0]?.n === 'gemini';
  const r = await llmJSON(STAFF_SYS, prompt, { task: 'portrait', temp: 0.3, max: 2000, grounded });
  return applyStaffPortrait(m, Array.isArray(r?.players) ? r.players[0] : r);
}
app.post('/api/admin/staff/portrait', admin, async (req, res) => {
  const m = (db.staff || []).find((x: any) => x.id === req.body.id);
  if (!m) return fail(res, 'Специалист не найден');
  if (!hasLLM()) return fail(res, 'Не настроен ключ нейросети для генерации портрета');
  try {
    if (!(await staffPortrait(m))) return fail(res, 'Нейросеть не вернула портрет. Заполните карточку вручную.');
    save();
    res.json({ ok: 1, member: m });
  } catch (e: any) {
    fail(res, 'Ошибка генерации портрета: ' + e.message);
  }
});
// портреты всем, у кого он ещё не сделан (или всем сразу при all=true), не больше 25 за вызов
app.post('/api/admin/staff/portraits-all', admin, async (req, res) => {
  if (!hasLLM()) return fail(res, 'Не настроен ключ нейросети для генерации портретов');
  let list = (db.staff || []).filter((x: any) => req.body.all ? true : x.pending);
  if (req.body.teamId) list = list.filter((x: any) => x.teamId === req.body.teamId);
  const total = list.length;
  list = list.slice(0, 25);
  let updated = 0, failed = 0;
  for (const m of list) {
    try { if (await staffPortrait(m)) updated++; else failed++; } catch { failed++; }
    save();
  }
  res.json({ ok: 1, updated, failed, left: Math.max(0, total - list.length) });
});

app.post('/api/admin/coach', admin, async (req, res) => {
  const { name, role = 'head', teamId = '', age: reqAge, nationality: reqNat, specialty: reqSpec, favoriteFormation = '4-3-3', bio: reqBio, style: reqStyle } = req.body;
  if (!name) return fail(res, 'Укажите ФИО специалиста');
  if (!db.staff) db.staff = [];
  const validRole: StaffRole = STAFF_ROLE_LIST.includes(role) ? role : 'head';
  const roleMeta = STAFF_ROLES[validRole] || STAFF_ROLES.head;

  let age = Number(reqAge) || 45;
  let nat = reqNat ? String(reqNat).trim() : 'Россия';
  let specialty = reqSpec ? String(reqSpec).trim() : roleMeta.desc;
  let bio = reqBio ? String(reqBio).trim() : '';

  if (hasLLM() && !bio) {
    try {
      const tm = team(teamId);
      const prompt = `Составь профиль футбольного специалиста на должность "${roleMeta.title}" (${name})${tm ? ` в клуб "${tm.name}"` : ''}.
Определи его примерный возраст (число), гражданство (на русском), узкую специализацию (1 предложение) и подробный опыт/биографию (2-3 предложения).
Ответь строго в JSON: { "age": 46, "nat": "Россия", "specialty": "...", "bio": "..." }`;
      const info = await llmJSON('Ты — футбольная спортивная энциклопедия.', prompt, { temp: 0.4, max: 500 });
      if (info.age) age = Number(info.age) || age;
      if (info.nat) nat = String(info.nat);
      if (info.specialty) specialty = String(info.specialty);
      if (info.bio) bio = String(info.bio);
    } catch {}
  }

  const tm = team(teamId);
  const member: StaffMember = {
    id: 'staff_' + uid(),
    name: String(name).trim(),
    role: validRole,
    roleTitle: roleMeta.title,
    teamId: teamId || '',
    teamName: tm ? tm.name : '',
    age,
    nationality: nat,
    specialty,
    favoriteFormation: validRole === 'head' ? (favoriteFormation || '4-3-3') : undefined,
    style: validRole === 'head' ? (reqStyle || 'possession') : undefined,
    styleTitle: validRole === 'head' ? 'Сбалансированный стиль' : undefined,
    bio: bio || `${name} — ${roleMeta.title.toLowerCase()}${tm ? ` клуба «${tm.name}»` : ''}. ${specialty}.`
  };

  db.staff.push(member);
  save();
  res.json({ ok: 1, coach: member, member });
});

app.post('/api/admin/coach/assign', admin, (req, res) => {
  const { coachId, teamId, role } = req.body;
  const c = (db.staff || []).find((x: any) => x.id === coachId);
  if (!c) return fail(res, 'Специалист не найден');
  c.teamId = teamId || '';
  const tm = team(teamId);
  c.teamName = tm ? tm.name : '';
  if (role && STAFF_ROLE_LIST.includes(role)) {
    c.role = role;
    c.roleTitle = STAFF_ROLES[role as StaffRole]?.title || c.roleTitle;
  }
  save();
  res.json({ ok: 1, coach: c, member: c });
});

app.post('/api/admin/coach/update', admin, (req, res) => {
  const { id, name, role, teamId, age, nationality, specialty, favoriteFormation, bio } = req.body;
  const c = (db.staff || []).find((x: any) => x.id === id);
  if (!c) return fail(res, 'Специалист не найден');
  if (name) c.name = String(name).trim();
  if (role && STAFF_ROLE_LIST.includes(role)) {
    c.role = role;
    c.roleTitle = STAFF_ROLES[role as StaffRole]?.title || c.roleTitle;
  }
  if (teamId !== undefined) {
    c.teamId = teamId || '';
    const tm = team(teamId);
    c.teamName = tm ? tm.name : '';
  }
  if (age) c.age = Number(age) || c.age;
  if (nationality) c.nationality = String(nationality).trim();
  if (specialty) c.specialty = String(specialty).trim();
  if (favoriteFormation && c.role === 'head') c.favoriteFormation = String(favoriteFormation).trim();
  if (bio) c.bio = String(bio).trim();
  if (bio || specialty) c.pending = false;
  save();
  res.json({ ok: 1, coach: c, member: c });
});

app.post('/api/admin/coach/delete', admin, (req, res) => {
  const { id } = req.body;
  const idx = (db.staff || []).findIndex((x: any) => x.id === id);
  if (idx < 0) return fail(res, 'Специалист не найден');
  db.staff.splice(idx, 1);
  save();
  res.json({ ok: 1 });
});

app.post('/api/admin/club/custom', admin, (req, res) => {
  const { name, city, country } = req.body;
  if (!name) return fail(res, 'Укажите название клуба');
  const nm = String(name).trim();
  const existing = db.teams.find((t: any) => t.name.toLowerCase() === nm.toLowerCase());
  if (existing) return res.json({ ok: 1, team: existing });
  const newTeam = {
    id: 'tm_' + uid(),
    name: nm,
    comp: 'friendly',
    city: String(city || '').trim(),
    country: String(country || '').trim(),
    lat: null,
    lon: null,
    stadium: '',
    logo: getTeamLogo(nm, '', 'friendly'),
    code: Math.random().toString(36).slice(2, 6).toUpperCase() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase()
  };
  db.teams.push(newTeam);
  save();
  res.json({ ok: 1, team: newTeam });
});

/* ───────── ТОВАРИЩЕСКИЕ МАТЧИ В ПАУЗЫ НА СБОРНЫЕ ─────────
   Клуб выбирает соперника, место, дату (только внутри паузы на сборные), условия и бюджет матча.
   • соперник из РПЛ  → нужны согласия клуба-соперника И администратора;
   • соперник из любой другой лиги или зарубежный клуб → решает только администратор.
   После всех согласий бюджет списывается у инициатора (и зачисляется сопернику, см. FRIENDLY_PAY_OPPONENT),
   а в календаре появляется матч соревнования «Товарищеские матчи». */
const fmtEuro = (n: number) => '€' + Math.round(Number(n) || 0).toLocaleString('ru-RU');
const cleanTxt = (v: any, max: number) => String(v ?? '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, max);

function friendlyBreaks() {
  return (db.internationalBreaks || DEFAULT_INTERNATIONAL_BREAKS).filter((b: any) => String(b.id).startsWith('ib_') || String(b.id).startsWith('winter_break'));
}
function friendlyBreakFor(date: string) {
  return friendlyBreaks().find((b: any) => date >= b.start && date <= b.end) || null;
}
function upcomingFriendlyBreaks() {
  return friendlyBreaks()
    .sort((a: any, b: any) => a.start.localeCompare(b.start))
    .map((b: any) => ({ id: b.id, name: b.name, start: b.start, end: b.end }));
}
/* нужен ли ответ клуба-соперника: только для клубов РПЛ */
const friendlyNeedsClub = (opp: any) => opp?.comp === 'rpl';

function friendlyConflict(tid: string, date: string): string | null {
  const clash = (db.fixtures || []).find((f: any) => (f.home === tid || f.away === tid) && (f.gameDate || f.date) === date);
  return clash ? `У клуба «${tn(tid)}» уже назначен матч на ${date}` : null;
}

function expireFriendlies(): boolean {
  const today = todayMsk();
  let ch = false;
  for (const r of (db.friendlyRequests ||= [])) {
    const checkDate = r.realDate || r.date;
    if (r.status === 'pending' && checkDate < today) {
      r.status = 'expired';
      r.rejectReason = 'Настоящая дата матча прошла, а заявка не была полностью согласована';
      r.resolvedAt = new Date().toISOString();
      ch = true;
    }
  }
  return ch;
}

function friendlyPlace(r: any) {
  const A = team(r.clubId), B = team(r.opponentId);
  const nm = (t: any) => t?.stadium || (t ? `Стадион «${t.name}»` : '');
  if (r.venue === 'home') return { home: r.clubId, away: r.opponentId, stadium: nm(A), city: A?.city || '', neutral: false };
  if (r.venue === 'away') return { home: r.opponentId, away: r.clubId, stadium: nm(B), city: B?.city || '', neutral: false };
  return {
    home: r.clubId, away: r.opponentId,
    stadium: r.neutralStadium || 'Нейтральное поле',
    city: r.neutralCity || A?.city || '',
    neutral: true
  };
}

const pubFriendly = (r: any) => {
  const B = team(r.opponentId);
  const place = friendlyPlace(r);
  const gameDate = r.gameDate || r.date;
  const gameTime = r.gameTime || r.time || '15:00';
  const realDate = r.realDate || r.date;
  const realTime = r.realTime || r.time || '19:00';
  return {
    id: r.id,
    clubId: r.clubId, clubName: tn(r.clubId), clubLogo: teamLogo(r.clubId), clubComp: team(r.clubId)?.comp || '',
    opponentId: r.opponentId, opponentName: tn(r.opponentId), opponentLogo: teamLogo(r.opponentId),
    opponentComp: B?.comp || '', opponentCompName: compOf(B?.comp)?.name || (B?.country ? `Зарубежный клуб · ${B.country}` : 'Другая лига'),
    venue: r.venue,
    venueText: r.venue === 'home' ? `У хозяев: ${tn(r.clubId)}` : r.venue === 'away' ? `В гостях: ${tn(r.opponentId)}` : `Нейтральное поле`,
    stadium: place.stadium, city: place.city,
    date: gameDate, time: gameTime,
    gameDate, gameTime,
    realDate, realTime,
    breakName: friendlyBreakFor(gameDate)?.name || '',
    conditions: r.conditions,
    budget: r.budget, formattedBudget: fmtEuro(r.budget),
    needOpponentApproval: !!r.needOpponentApproval,
    opponentApproval: r.opponentApproval,
    adminApproval: r.adminApproval,
    status: r.status,
    rejectReason: r.rejectReason || '',
    fixtureId: r.fixtureId || null,
    createdAt: r.createdAt, resolvedAt: r.resolvedAt || null
  };
};

/* Когда получены все нужные согласия — проверяем всё ещё раз, списываем бюджет и создаём матч */
function tryFinalizeFriendly(r: any): { executed: boolean; error?: string } {
  if (r.status === 'approved') return { executed: true };
  if (r.status !== 'pending') return { executed: false };
  const clubOk = !r.needOpponentApproval || r.opponentApproval === 'approved';
  if (!(clubOk && r.adminApproval === 'approved')) return { executed: false };

  const reject = (why: string) => {
    r.status = 'rejected';
    r.rejectReason = why;
    r.resolvedAt = new Date().toISOString();
    return { executed: false, error: why };
  };
  const A = team(r.clubId), B = team(r.opponentId);
  if (!A || !B) return reject('Один из клубов не найден');
  const gameDate = r.gameDate || r.date;
  const gameTime = r.gameTime || r.time || '15:00';
  const realDate = r.realDate || r.date;
  const realTime = r.realTime || r.time || '19:00';

  if (realDate < todayMsk()) return reject('Настоящая дата матча уже прошла');
  if (!friendlyBreakFor(gameDate)) return reject('Игровая дата не попадает в официальную паузу на сборные');
  const clash = friendlyConflict(A.id, gameDate) || friendlyConflict(B.id, gameDate);
  if (clash) return reject(clash);

  ensureInitialBudgets();
  const budget = Math.round(Number(r.budget) || 0);
  const prevA = A.budget || 0;
  if (prevA < budget) return reject(`У клуба «${A.name}» недостаточно средств: ${fmtEuro(prevA)} из требуемых ${fmtEuro(budget)}`);

  if (!Array.isArray(db.budgetHistory)) db.budgetHistory = [];
  const nowIso = new Date().toISOString();
  A.budget = prevA - budget;
  db.budgetHistory.push({
    id: uid(), teamId: A.id, teamName: A.name, amount: -budget, prevBudget: prevA, newBudget: A.budget,
    type: 'friendly_match', typeLabel: 'Товарищеский матч',
    description: `Товарищеский матч с «${B.name}» (игровая дата: ${gameDate}, реальная: ${realDate}): бюджет матча -${fmtEuro(budget)}`,
    date: nowIso, byAdmin: false
  });
  if (FRIENDLY_PAY_OPPONENT) {
    const prevB = B.budget || 0;
    B.budget = prevB + budget;
    db.budgetHistory.push({
      id: uid(), teamId: B.id, teamName: B.name, amount: budget, prevBudget: prevB, newBudget: B.budget,
      type: 'friendly_match', typeLabel: 'Товарищеский матч',
      description: `Товарищеский матч с «${A.name}» (игровая дата: ${gameDate}, реальная: ${realDate}): получен бюджет матча +${fmtEuro(budget)}`,
      date: nowIso, byAdmin: false
    });
  }

  // у зарубежных/«чужих» клубов может не быть состава — создаём, чтобы матч можно было сыграть
  for (const t of [A, B]) {
    if (squadOf(t.id).length === 0) {
      try {
        const ids: string[] = [];
        for (const p of generateFullSquad(t)) { db.players.push(p); ids.push(p.id); }
        db.squads[t.id] = ids;
      } catch (err: any) { console.error('friendly: не удалось создать состав', t.name, err?.message); }
    }
  }

  const place = friendlyPlace(r);
  const f: any = {
    id: uid(),
    season: S(),
    comp: FRIENDLY_COMP,
    round: 1,
    label: 'Товарищеский матч',
    note: r.conditions,
    date: gameDate, time: gameTime,
    gameDate: gameDate, gameTime: gameTime,
    realDate: realDate, realTime: realTime,
    home: place.home, away: place.away,
    status: 'scheduled', hg: null, ag: null, pos: 0,
    friendlyId: r.id,
    friendlyBudget: budget,
    friendlyConditions: r.conditions,
    neutralField: place.neutral,
    stadium: place.neutral ? `${place.stadium} (нейтральное поле${place.city ? ', г. ' + place.city : ''})` : place.stadium,
    city: place.city || undefined
  };
  if (!f.city) delete f.city;
  db.fixtures.push(f);
  try { assignFixtureWeather(f); } catch (err: any) { console.error('friendly weather:', err?.message); }

  r.status = 'approved';
  r.fixtureId = f.id;
  r.resolvedAt = nowIso;
  invalidateAgg();
  try {
    tg(`🤝 <b>Товарищеский матч согласован</b>\n«${esc(tn(place.home))}» — «${esc(tn(place.away))}»\n🎮 Игровое: <b>${esc(gameDate)} ${esc(gameTime)}</b>\n⏰ Настоящее: <b>${esc(realDate)} ${esc(realTime)} МСК</b>\n🏟 ${esc(place.stadium)}\n💶 Бюджет матча: <b>${esc(fmtEuro(budget))}</b>\n<i>${esc(r.conditions)}</i>`);
  } catch { /* telegram не критичен */ }
  return { executed: true };
}

/* данные для кабинета клуба */
function friendlyForClub(tid: string) {
  expireFriendlies();
  const all: any[] = db.friendlyRequests || [];
  const byNew = (a: any, b: any) => String(b.createdAt).localeCompare(String(a.createdAt));
  const incoming = all.filter(r => r.opponentId === tid && r.needOpponentApproval && r.status === 'pending' && r.opponentApproval === 'pending').sort(byNew).map(pubFriendly);
  const outgoing = all.filter(r => r.clubId === tid).sort(byNew).slice(0, 30).map(pubFriendly);
  const history = all.filter(r => r.opponentId === tid && !(r.status === 'pending' && r.opponentApproval === 'pending')).sort(byNew).slice(0, 15).map(pubFriendly);
  return { incoming, outgoing, history, breaks: upcomingFriendlyBreaks() };
}

app.post('/api/club/friendly/request', needClub, (req: any, res) => {
  expireFriendlies();
  const b = req.body || {};
  const A = team(req.tid);
  if (!A) return fail(res, 'Клуб не найден');
  const B = team(String(b.opponentId || ''));
  if (!B) return fail(res, 'Выберите команду-соперника');
  if (B.id === A.id) return fail(res, 'Нельзя пригласить на матч самого себя');

  const venue = ['home', 'away', 'neutral'].includes(b.venue) ? b.venue : '';
  if (!venue) return fail(res, 'Выберите место проведения матча');
  const neutralStadium = cleanTxt(b.neutralStadium, 80);
  const neutralCity = cleanTxt(b.neutralCity, 60);
  if (venue === 'neutral' && !neutralStadium && !neutralCity) return fail(res, 'Для нейтрального поля укажите стадион или город');

  // 1) Игровое время (виртуальный календарь)
  const gameDate = String(b.gameDate || b.date || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(gameDate)) return fail(res, 'Укажите игровую дату матча');
  if (!friendlyBreakFor(gameDate)) {
    const w = upcomingFriendlyBreaks().map((x: any) => `${x.start} — ${x.end} (${x.name})`).join('; ');
    return fail(res, `Игровая дата должна попадать в официальную паузу на сборные${w ? ': ' + w : ''}`);
  }
  let gameTime = String(b.gameTime || b.time || '15:00').trim();
  if (!/^\d{1,2}:\d{2}$/.test(gameTime)) return fail(res, 'Некорректное игровое время матча');
  if (gameTime.length === 4) gameTime = '0' + gameTime;

  // 2) Настоящее время (реальное время трансляции / матча по МСК)
  const realDate = String(b.realDate || todayMsk()).trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(realDate)) return fail(res, 'Укажите настоящее (реальное) число матча');
  if (realDate < todayMsk()) return fail(res, 'Реальная дата проведения матча не может быть в прошлом');
  let realTime = String(b.realTime || '19:00').trim();
  if (!/^\d{1,2}:\d{2}$/.test(realTime)) return fail(res, 'Некорректное настоящее (реальное) время матча');
  if (realTime.length === 4) realTime = '0' + realTime;

  const conditions = cleanTxt(b.conditions, 500);
  if (conditions.length < 3) return fail(res, 'Пропишите условия матча');

  const budget = Math.round(Number(b.budget));
  if (!Number.isFinite(budget) || budget <= 0) return fail(res, 'Укажите бюджет матча — бесплатных матчей не бывает');
  ensureInitialBudgets();
  if ((A.budget || 0) < budget) return fail(res, `Недостаточно средств: в бюджете клуба ${fmtEuro(A.budget || 0)}, а бюджет матча ${fmtEuro(budget)}`);

  if ((db.friendlyRequests ||= []).some((r: any) => r.status === 'pending' && r.clubId === A.id && r.opponentId === B.id && (r.gameDate || r.date) === gameDate)) {
    return fail(res, 'Такая заявка на эту игровую дату уже подана и ждёт решения');
  }
  const clash = friendlyConflict(A.id, gameDate) || friendlyConflict(B.id, gameDate);
  if (clash) return fail(res, clash);

  const needClub = friendlyNeedsClub(B);
  const r = {
    id: 'fr_' + uid(),
    clubId: A.id, opponentId: B.id,
    venue, neutralStadium, neutralCity,
    date: gameDate, time: gameTime,
    gameDate, gameTime,
    realDate, realTime,
    conditions, budget,
    needOpponentApproval: needClub,
    opponentApproval: needClub ? 'pending' : 'not_required',
    adminApproval: 'pending',
    status: 'pending',
    fixtureId: null as any,
    createdAt: new Date().toISOString()
  };
  db.friendlyRequests.unshift(r);
  save();
  try {
    tg(`🤝 <b>Заявка на товарищеский матч</b>\n«${esc(A.name)}» приглашает «${esc(B.name)}»\n🎮 Игровое: <b>${esc(gameDate)} ${esc(gameTime)}</b>\n⏰ Настоящее: <b>${esc(realDate)} ${esc(realTime)} МСК</b>\n🏟 ${esc(pubFriendly(r).venueText)}\n💶 Бюджет: <b>${esc(fmtEuro(budget))}</b>\n<i>${esc(conditions)}</i>\n${needClub ? 'Нужны согласия клуба-соперника и администратора.' : 'Требуется решение администратора.'}`);
  } catch { /* telegram не критичен */ }
  res.json({
    ok: 1,
    request: pubFriendly(r),
    message: needClub
      ? `Заявка отправлена клубу «${B.name}» и администратору. Матч состоится, когда её примут оба.`
      : `Заявка отправлена администратору — «${B.name}» играет не в РПЛ, поэтому решение за админом.`
  });
});

app.post('/api/club/friendly/respond', needClub, (req: any, res) => {
  expireFriendlies();
  const { requestId, action } = req.body || {};
  const r = (db.friendlyRequests || []).find((x: any) => x.id === requestId);
  if (!r) return fail(res, 'Заявка не найдена');
  if (r.status !== 'pending') return fail(res, 'Заявка уже закрыта');

  if (action === 'cancel') {
    if (r.clubId !== req.tid) return fail(res, 'Отозвать заявку может только пригласивший клуб');
    r.status = 'cancelled';
    r.rejectReason = `Заявка отозвана клубом «${tn(r.clubId)}»`;
    r.resolvedAt = new Date().toISOString();
    save();
    return res.json({ ok: 1, message: 'Заявка отозвана' });
  }
  if (r.opponentId !== req.tid || !r.needOpponentApproval) return fail(res, 'Эта заявка не требует вашего ответа');
  if (r.opponentApproval !== 'pending') return fail(res, 'Вы уже ответили на эту заявку');

  if (action === 'approve') {
    const clash = friendlyConflict(r.opponentId, r.date);
    if (clash) return fail(res, clash);
    r.opponentApproval = 'approved';
    const out = tryFinalizeFriendly(r);
    save();
    return res.json({
      ok: 1, approved: true, executed: out.executed,
      message: out.executed
        ? 'Матч согласован всеми сторонами и добавлен в календарь!'
        : out.error ? `Заявка закрыта: ${out.error}`
        : 'Вы приняли приглашение. Ждём решения администратора.'
    });
  }
  if (action === 'reject') {
    r.opponentApproval = 'rejected';
    r.status = 'rejected';
    r.rejectReason = `Клуб «${tn(r.opponentId)}» отклонил приглашение`;
    r.resolvedAt = new Date().toISOString();
    save();
    return res.json({ ok: 1, rejected: true, message: 'Приглашение отклонено' });
  }
  return fail(res, 'Неизвестное действие');
});

app.get('/api/admin/friendly-requests', admin, (req, res) => {
  expireFriendlies();
  const list: any[] = db.friendlyRequests || [];
  res.json({
    pending: list.filter(r => r.status === 'pending').sort((a, b) => a.date.localeCompare(b.date)).map(pubFriendly),
    closed: list.filter(r => r.status !== 'pending').sort((a, b) => String(b.resolvedAt || b.createdAt).localeCompare(String(a.resolvedAt || a.createdAt))).slice(0, 40).map(pubFriendly),
    breaks: upcomingFriendlyBreaks()
  });
});

app.post('/api/admin/friendly/resolve', admin, (req, res) => {
  expireFriendlies();
  const { id, action, comment } = req.body || {};
  const r = (db.friendlyRequests || []).find((x: any) => x.id === id);
  if (!r) return fail(res, 'Заявка не найдена');
  if (r.status !== 'pending') return fail(res, 'Заявка уже закрыта');
  if (action === 'approve') {
    r.adminApproval = 'approved';
    if (comment) r.adminComment = cleanTxt(comment, 200);
    const out = tryFinalizeFriendly(r);
    save();
    return res.json({
      ok: 1, executed: out.executed, error: out.error,
      message: out.executed
        ? 'Матч добавлен в календарь, бюджет списан.'
        : out.error ? `Заявка закрыта: ${out.error}`
        : `Одобрено. Ждём ответа клуба «${tn(r.opponentId)}».`
    });
  }
  if (action === 'reject') {
    r.adminApproval = 'rejected';
    r.status = 'rejected';
    r.rejectReason = cleanTxt(comment, 200) || 'Отклонено администратором';
    r.resolvedAt = new Date().toISOString();
    save();
    return res.json({ ok: 1, rejected: true, message: 'Заявка отклонена' });
  }
  return fail(res, 'Неизвестное действие');
});

/* ───────── турниры во время зимней и летней паузы ───────── */
app.get('/api/tournaments', (req, res) => {
  res.json({ tournaments: db.tournaments || [] });
});

app.post('/api/admin/tournament', admin, (req, res) => {
  const { name, pauseType, country, city, startDate, teamIds } = req.body;
  if (!name || !country || !city || !startDate) return fail(res, 'Заполните название, страну, город и дату');
  const teams = Array.isArray(teamIds) ? teamIds.filter((id: string) => team(id)) : [];
  if (teams.length < 2) return fail(res, 'Выберите минимум 2 команды');
  const tid = 'trn_' + uid();
  const compId = 'tournament_' + tid;
  const trn = {
    id: tid,
    compId,
    name: String(name).trim(),
    pauseType: pauseType === 'winter' ? 'winter' : 'summer',
    country: String(country).trim(),
    city: String(city).trim(),
    startDate,
    teamIds: teams,
    createdAt: new Date().toISOString()
  };
  db.tournaments.push(trn);

  // Генерируем круговой турнир
  const arr: (string | null)[] = [...teams];
  if (arr.length % 2) arr.push(null);
  const n = arr.length;
  let dayOffset = 0;
  for (let k = 0; k < n - 1; k++) {
    const matchDate = addDays(startDate, dayOffset);
    let slot = 0;
    for (let i = 0; i < n / 2; i++) {
      const a = arr[i], b = arr[n - 1 - i];
      if (a && b) {
        const fxObj: any = {
          id: uid(),
          season: S(),
          comp: compId,
          round: k + 1,
          date: matchDate,
          time: ['14:00', '17:00', '19:30'][slot % 3],
          home: k % 2 ? b : a,
          away: k % 2 ? a : b,
          status: 'scheduled',
          hg: null,
          ag: null,
          pos: 0,
          tournamentName: trn.name,
          venue: `${trn.city}, ${trn.country}`
        };
        assignReferee(fxObj);
        db.fixtures.push(fxObj);
        slot++;
      }
    }
    arr.splice(1, 0, arr.pop()!);
    dayOffset += 3;
  }
  save();
  res.json({ ok: 1, tournament: trn });
});

app.delete('/api/admin/tournament/:id', admin, (req, res) => {
  const trn = db.tournaments.find((x: any) => x.id === req.params.id);
  if (!trn) return fail(res, 'Турнир не найден');
  db.tournaments = db.tournaments.filter((x: any) => x.id !== req.params.id);
  db.fixtures = db.fixtures.filter((f: any) => f.comp !== trn.compId);
  save();
  res.json({ ok: 1 });
});

/* ───────── прямой трансфер админа (с указанием суммы, сохранением статистики и согласованием РПЛ) ───────── */
app.post('/api/admin/transfer/direct', admin, (req, res) => {
  const { pid, toTeamId, transferType, fee, force } = req.body;
  const p = player(pid);
  const toTeam = team(toTeamId);
  if (!p || !toTeam) return fail(res, 'Игрок или клуб не найден');
  const fromTeamId = p.teamId;
  const fromTeam = team(fromTeamId);

  const feeStr = String(fee || '€5.0M').trim();
  const feeNum = parseFeeAmount(feeStr);
  const loanMap: Record<string, string> = {
    'loan_0.5': 'Аренда (0.5 года)',
    'loan_1': 'Аренда (1 год)',
    'loan_1.5': 'Аренда (1.5 года)',
    'loan_2': 'Аренда (2 года)',
    'loan_mandatory_rpl': 'Аренда с обязательным выкупом'
  };
  const isMandatoryBuyout = transferType === 'loan_mandatory_rpl' || !!req.body.mandatoryBuyout;
  const isLoan = !!loanMap[transferType] || isMandatoryBuyout;
  const buyoutFeeStr = isMandatoryBuyout ? String(req.body.buyoutFee || feeStr || '€8.0M').trim() : null;
  const loanCondition = isMandatoryBuyout ? String(req.body.loanCondition || req.body.buyoutCondition || 'Сохранение прописки в РПЛ').trim() : null;
  const sellOnPct = Math.min(90, Math.max(0, Number(req.body.sellOnPercent) || 0));

  let note = isMandatoryBuyout
    ? `Аренда с обязательным выкупом (${buyoutFeeStr})${loanCondition ? ` при условии: «${loanCondition}»` : ''}`
    : (loanMap[transferType] || 'Полноценный трансфер');

  if (sellOnPct > 0) {
    note += ` · Sell-on clause ${sellOnPct}%`;
  }

  const isRplToRpl = fromTeam?.comp === 'rpl' && toTeam?.comp === 'rpl';

  const trObj: any = {
    id: uid(),
    pid: p.id,
    playerName: p.name,
    pos: p.pos || 'ЦП',
    from: fromTeamId || 'free_agent',
    fromName: fromTeam?.name || 'Свободный агент',
    to: toTeamId,
    toName: toTeam.name,
    fee: feeStr,
    feeAmount: feeNum,
    type: isMandatoryBuyout ? 'loan_mandatory_rpl' : (isLoan ? 'loan' : 'transfer'),
    mandatoryBuyoutOnRplRetention: isMandatoryBuyout,
    mandatoryBuyout: isMandatoryBuyout,
    buyoutFee: buyoutFeeStr,
    loanCondition: loanCondition,
    sellOnPercent: sellOnPct,
    note,
    status: 'pending',
    isRplToRpl,
    adminApproval: 'approved',
    clubApproval: (isRplToRpl && !force) ? 'pending' : 'approved',
    clubApprovedBy: fromTeamId,
    date: new Date().toISOString().slice(0, 10),
    byAdmin: true
  };

  db.transfers.unshift(trObj);

  if (!isRplToRpl || force) {
    executeTransferIfBothApproved(trObj);
    save();
    return res.json({
      ok: 1,
      executed: true,
      player: p,
      transfer: trObj,
      message: `Трансфер игрока ${p.name} в «${toTeam.name}» (${feeStr}) успешно оформлен.`
    });
  }

  save();
  res.json({
    ok: 1,
    executed: false,
    pendingClub: true,
    transfer: trObj,
    message: `Запрос на ${isLoan ? 'аренду' : 'трансфер'} игрока ${p.name} (${feeStr}) отправлен владельцу «${fromTeam?.name}». Переход состоится при согласии клуба.`
  });
});

/* ───────── Сборная России (паузы, расширенный/итоговый состав, товарищеские матчи, архив) ───────── */
function ensureNationalTeam() {
  db.nationalTeam ||= {
    current: {
      title: 'Ближайшая пауза на матчи сборных',
      stage: 'extended',
      extended: [],
      final: [],
      matches: []
    },
    archive: []
  };
  return db.nationalTeam;
}

function enrichNationalBreak(brk: any) {
  const enrichIds = (ids: string[]) => (ids || []).map((id: string) => {
    const p = player(id);
    if (!p) return null;
    return {
      id: p.id,
      name: p.name,
      pos: p.pos,
      teamId: p.teamId,
      teamName: tn(p.teamId),
      teamLogo: teamLogo(p.teamId),
      ovr: p.ovr || 70,
      goals: p.goals || 0,
      assists: p.assists || 0,
      matches: p.matches || 0,
      rating: p.rating || 0
    };
  }).filter(Boolean);
  const matches = (brk.matches || []).map((m: any) => ({
    ...m,
    gameDate: m.gameDate || m.date,
    gameTime: m.gameTime || m.time || '19:00',
    realDate: m.realDate || m.date,
    realTime: m.realTime || m.time || '19:00',
    russiaLogo: '/assets/aistudio/russia_russia-national-team.football-logos.cc_2a5e3ddc.svg',
    opponentLogo: teamLogo(m.opponent)
  }));
  return {
    ...brk,
    teamLogo: '/assets/aistudio/russia_russia-national-team.football-logos.cc_2a5e3ddc.svg',
    matches,
    extendedPlayers: enrichIds(brk.extended),
    finalPlayers: enrichIds(brk.final)
  };
}

app.get('/api/national', (req, res) => {
  const nt = ensureNationalTeam();
  const nationalBreaks = (db.internationalBreaks || DEFAULT_INTERNATIONAL_BREAKS).filter((b: any) => b.id.startsWith('ib_'));
  res.json({
    current: enrichNationalBreak(nt.current),
    archive: (nt.archive || []).map(enrichNationalBreak),
    breaks: nationalBreaks
  });
});

app.post('/api/admin/national/generate', admin, async (req, res) => {
  const nt = ensureNationalTeam();
  const stage = req.body.stage === 'final' ? 'final' : 'extended';
  const count = stage === 'final' ? 25 : 40;
  if (req.body.title) nt.current.title = String(req.body.title).trim();

  let pool = db.players.filter((p: any) => !p.nat || p.nat === 'RUS' || p.nat === 'Россия');
  if (stage === 'final' && nt.current.extended?.length >= 25) {
    const extSet = new Set(nt.current.extended);
    pool = pool.filter((p: any) => extSet.has(p.id));
  }

  const sortedPool = [...pool].sort((a: any, b: any) =>
    ((b.rating || 0) * 10 + (b.goals || 0) * 3 + (b.assists || 0) * 2 + (b.ovr || 70) * 0.2) -
    ((a.rating || 0) * 10 + (a.goals || 0) * 3 + (a.assists || 0) * 2 + (a.ovr || 70) * 0.2)
  );

  let chosenIds: string[] = [];
  if (hasLLM() && sortedPool.length > 0) {
    try {
      const candidates = sortedPool.slice(0, 75).map((p: any) =>
        `${p.id}|${p.name}|${p.pos}|${tn(p.teamId)}|OVR:${p.ovr || 70}|М:${p.matches || 0}|Г:${p.goals || 0}|П:${p.assists || 0}|Рейт:${Number(p.rating || 0).toFixed(2)}`
      ).join('\n');
      const sys = 'Ты — главный тренер сборной России по футболу. Выбирай состав строго по позиции (минимум 3 вратаря, 8 защитников, 8 полузащитников, 4 нападающих) и текущей игровой форме/статистике.';
      const prompt = `Сформируй ${stage === 'final' ? 'ИТОГОВЫЙ состав (ровно 25 игроков)' : 'РАСШИРЕННЫЙ состав (ровно 40 игроков)'} сборной России на ближайшую паузу из списка кандидатов:\n${candidates}\n\nВерни JSON: {"ids": ["id1", "id2", ...]}`;
      const raw = await llm(sys, prompt, { json: true, task: 'national_squad', temp: 0.3, max: 2000 });
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed.ids)) {
        const validSet = new Set(sortedPool.map((p: any) => p.id));
        chosenIds = parsed.ids.filter((id: string) => validSet.has(id)).slice(0, count);
      }
    } catch (e: any) {
      console.error('national/generate:', e.message);
    }
  }

  if (chosenIds.length < Math.min(count, sortedPool.length)) {
    const have = new Set(chosenIds);
    for (const p of sortedPool) {
      if (!have.has(p.id)) {
        chosenIds.push(p.id);
        have.add(p.id);
        if (chosenIds.length >= count) break;
      }
    }
  }

  nt.current.stage = stage;
  nt.current[stage] = chosenIds;
  save();
  res.json({ ok: 1, current: enrichNationalBreak(nt.current) });
});

app.post('/api/admin/national/squad', admin, (req, res) => {
  const nt = ensureNationalTeam();
  const { action, pid, stage } = req.body;
  const st = stage || nt.current.stage || 'extended';
  nt.current[st] ||= [];
  if (action === 'add' && pid) {
    if (!nt.current[st].includes(pid)) nt.current[st].push(pid);
  } else if (action === 'remove' && pid) {
    nt.current[st] = nt.current[st].filter((id: string) => id !== pid);
  } else if (action === 'stage' && (stage === 'extended' || stage === 'final')) {
    nt.current.stage = stage;
  }
  save();
  res.json({ ok: 1, current: enrichNationalBreak(nt.current) });
});

app.post('/api/admin/national/match', admin, (req, res) => {
  const nt = ensureNationalTeam();
  const { opponent, date, time, gameDate, gameTime, realDate, realTime, home } = req.body;
  if (!opponent) return fail(res, 'Укажите соперника');
  const gDate = String(gameDate || date || '').trim();
  if (!gDate) return fail(res, 'Укажите игровую дату матча');
  const nationalBreaks = (db.internationalBreaks || DEFAULT_INTERNATIONAL_BREAKS).filter((b: any) => b.id.startsWith('ib_'));
  const isValidDate = nationalBreaks.some((b: any) => gDate >= b.start && gDate <= b.end);
  if (!isValidDate) return fail(res, 'Матч сборной может проводиться только в даты официальных пауз на сборные!');

  const gTime = String(gameTime || time || '19:00').trim();
  const rDate = String(realDate || todayMsk()).trim();
  const rTime = String(realTime || '19:00').trim();

  nt.current.matches ||= [];
  nt.current.matches.push({
    id: uid(),
    opponent: String(opponent).trim(),
    date: gDate,
    time: gTime,
    gameDate: gDate,
    gameTime: gTime,
    realDate: rDate,
    realTime: rTime,
    home: home !== false
  });
  save();
  res.json({ ok: 1, current: enrichNationalBreak(nt.current) });
});

app.post('/api/admin/national/match/delete', admin, (req, res) => {
  const nt = ensureNationalTeam();
  const matchId = req.body.matchId || req.body.id;
  if (matchId) {
    nt.current.matches = (nt.current.matches || []).filter((m: any) => m.id !== matchId);
    save();
  }
  res.json({ ok: 1, current: enrichNationalBreak(nt.current) });
});

app.post('/api/admin/national/archive', admin, (req, res) => {
  const nt = ensureNationalTeam();
  nt.archive ||= [];
  nt.archive.unshift({
    ...nt.current,
    archivedAt: new Date().toISOString().slice(0, 10)
  });
  nt.current = {
    title: 'Следующая пауза на матчи сборных',
    stage: 'extended',
    extended: [],
    final: [],
    matches: []
  };
  save();
  res.json({ ok: 1 });
});

app.post('/api/admin/friendlies/generate', admin, (req, res) => {
  const yCur = parseInt(String(db.settings?.season || S()).slice(0, 4), 10) || 2026;
  db.internationalBreaks = getSeasonBreaks(yCur);
  ensureSeasonFriendlies(yCur);
  invalidateAgg();
  save();
  const natCount = (db.nationalTeam?.current?.matches || []).length;
  const clubCount = (db.fixtures || []).filter((f: any) => f.comp === FRIENDLY_COMP).length;
  res.json({ ok: 1, breaks: db.internationalBreaks, nationalMatches: natCount, clubMatches: clubCount });
});

/* ───────── проверка состава на реализм (ИИ, только админ) ───────── */
app.post('/api/admin/check-squad', admin, async (req, res) => {
  const t = team(req.body.teamId);
  if (!t) return fail(res, 'Клуб не найден');
  const sq = squadOf(t.id);
  if (!sq.length) return res.json({ realistic: true, summary: 'Состав пуст.', flaggedPlayers: [] });

  const squadText = sq.map((p: any) => `${p.name} (${p.pos}, ${ageOfPlayer(p) ?? 25} лет, ${p.nat || 'RUS'}, OVR ${p.ovr || 70})`).join('\n');
  if (hasLLM()) {
    try {
      const prompt = `Ты — футбольный скаут и эксперт по российскому футболу. Проверь состав клуба "${t.name}" (лига: ${t.comp.toUpperCase()}) на реализм.
Выяви нереалистичных игроков (например, мировых суперзвёзд уровня Месси, Роналду, Мбаппе в середняках/аутсайдерах РПЛ или ФНЛ, несоответствие уровня лиги, странные имена).
Состав:
${squadText}

Ответь строго в JSON:
{
  "realistic": true/false,
  "summary": "краткий вывод по составу на русском (2-3 предложения)",
  "flaggedPlayers": [
    { "name": "Имя игрока", "reason": "почему нереалистично", "suggestion": "кем заменить или что исправить" }
  ]
}`;
      const r = await llmJSON('Ты — строгий футбольный эксперт по реализму составов.', prompt, { temp: 0.3, max: 2000 });
      return res.json({
        realistic: !!r.realistic,
        summary: r.summary || 'Проверка завершена.',
        flaggedPlayers: Array.isArray(r.flaggedPlayers) ? r.flaggedPlayers : []
      });
    } catch (e: any) {
      console.error('check-squad:', e.message);
    }
  }
  // Fallback без LLM
  const stars = ['месси', 'messi', 'роналду', 'ronaldo', 'мбаппе', 'mbappe', 'холанд', 'haaland', 'неймар', 'neymar', 'винициус', 'vinicius', 'беллингем', 'bellingham'];
  const flagged = sq.filter((p: any) => stars.some(s => String(p.name || '').toLowerCase().includes(s))).map((p: any) => ({
    name: p.name,
    reason: `Игрок мирового уровня (${p.name}) нереалистичен для клуба ${t.name}`,
    suggestion: 'Заменить на игрока уровня РПЛ/ФНЛ'
  }));
  res.json({
    realistic: flagged.length === 0,
    summary: flagged.length ? `Обнаружено ${flagged.length} нереалистичных игроков в составе ${t.name}.` : `Состав клуба ${t.name} выглядит реалистично.`,
    flaggedPlayers: flagged
  });
});

/* ───────── интеллектуальный скаут и обогащение карточки игрока из Европы ───────── */
async function enrichEuropeanPlayer(playerName: string, feeStr?: string, transferType: string = 'transfer'): Promise<any> {
  const cleanName = String(playerName || '').trim();
  let pos = 'ЦП', age = 24, nationality = 'Иностранец', fromClub = 'Зарубежный клуб', marketValue = feeStr || '€10.0M', ovr = 75, style = 'Легионер с опытом выступлений в европейском чемпионате';

  if (hasLLM()) {
    try {
      const prompt = `Ты — международная футбольная база данных и скаутская служба Transfermarkt. Найди реального футболиста "${cleanName}".
Определи:
- pos: точное основное амплуа игрока (СТРОГО ОДНО ИЗ: ВР, ЦЗ, ЛЗ, ПЗ, ОП, ЦП, АП, ЛВ, ПВ, ЦФ)
- age: точный возраст (число)
- nationality: страна/гражданство на русском языке
- fromClub: текущий или последний реальный европейский или мировой клуб
- marketValue: ориентировочная рыночная стоимость Transfermarkt (например: "€15M", "€50M", "€4.5M")
- ovr: рейтинг мастерства OVR от 65 до 94 (число)
- style: стиль игры и сильные стороны (1 краткое предложение)

Ответь строго в JSON:
{
  "pos": "ЦФ",
  "age": 26,
  "nationality": "Швеция",
  "fromClub": "Спортинг",
  "marketValue": "€70M",
  "ovr": 86,
  "style": "Мощный завершитель атак с великолепным голевым чутьём и дриблингом"
}`;
      const info: any = await llmJSON('Ты — футбольная база данных.', prompt, { task: 'enrich-player', temp: 0.2, max: 400 });
      if (info?.pos && POSES.includes(info.pos)) pos = info.pos;
      if (info?.age && Number(info.age) >= 16 && Number(info.age) <= 45) age = Number(info.age);
      if (info?.nationality) nationality = String(info.nationality);
      if (info?.fromClub) fromClub = String(info.fromClub);
      if (info?.marketValue) marketValue = String(info.marketValue);
      if (info?.ovr && Number(info.ovr) >= 60 && Number(info.ovr) <= 99) ovr = Number(info.ovr);
      if (info?.style) style = String(info.style);
      return { pos, age, nationality, fromClub, marketValue, ovr, style };
    } catch (e: any) {
      console.warn('enrichEuropeanPlayer LLM error:', e.message);
    }
  }

  // Интеллектуальный эвристический скаут
  const feeNum = parseFeeAmount(feeStr);
  ovr = Math.min(92, Math.max(70, Math.round(72 + Math.min(15, feeNum * 0.4))));
  if (/гюлер|guler/i.test(cleanName)) {
    return { pos: 'АП', age: 21, nationality: 'Турция', fromClub: 'Реал Мадрид', marketValue: '€45M', ovr: 83, style: 'Виртуозный плеймейкер с филигранным видением поля и пасом' };
  }
  if (/дьёкереш|gyokeres|гиокереш/i.test(cleanName)) {
    return { pos: 'ЦФ', age: 28, nationality: 'Швеция', fromClub: 'Спортинг', marketValue: '€70M', ovr: 87, style: 'Неудержимый форвард-бомбардир таранного типа' };
  }
  if (/эндрик|endrick/i.test(cleanName)) {
    return { pos: 'ЦФ', age: 20, nationality: 'Бразилия', fromClub: 'Реал Мадрид', marketValue: '€60M', ovr: 82, style: 'Взрывной бразильский вундеркинд с пушечным ударом' };
  }
  if (/леонардо|leonardo/i.test(cleanName)) {
    return { pos: 'ЦФ', age: 23, nationality: 'Бразилия', fromClub: 'Бенфика', marketValue: '€25M', ovr: 80, style: 'Быстрый и пластичный бразильский нападающий штрафной площади' };
  }
  return { pos, age, nationality, fromClub, marketValue: feeStr || `€${(ovr - 65) * 1.5}M`, ovr, style };
}

/* ───────── заявки на трансфер от клубов (одиночные и списком + ИИ-поиск и проверка) ───────── */
app.post('/api/club/transfer-request', needClub, async (req: any, res) => {
  const { playerName, fee, transferType, list, text, players } = req.body;
  const buyerTeam = team(req.me.teamId);
  if (!buyerTeam) return fail(res, 'Клуб не найден');

  // Сбор списка игроков: одиночный или пакетный (списком)
  let itemsToProcess: Array<{ name: string; fee: string; type: string; mandatoryBuyout?: boolean; buyoutFee?: string; loanCondition?: string; sellOnPercent?: number }> = [];

  if (Array.isArray(players) && players.length > 0) {
    itemsToProcess = players.map((p: any) => {
      const isMand = String(p.transferType || p.type || '').includes('mandatory') || !!p.mandatoryBuyout;
      return {
        name: String(p.playerName || p.name || '').trim(),
        fee: String(p.fee || '€5.0M').trim(),
        type: isMand ? 'loan_mandatory_rpl' : (String(p.transferType || p.type || '').includes('loan') ? 'loan' : 'transfer'),
        mandatoryBuyout: isMand,
        buyoutFee: isMand ? String(p.buyoutFee || p.fee || '€8.0M').trim() : undefined,
        loanCondition: isMand ? String(p.loanCondition || p.buyoutCondition || 'Сохранение прописки в РПЛ').trim() : undefined,
        sellOnPercent: Math.min(90, Math.max(0, Number(p.sellOnPercent) || 0))
      };
    }).filter(x => x.name.length > 0);
  } else if (typeof (list || text) === 'string' && (list || text).trim().length > 0) {
    const rawLines = String(list || text).split('\n');
    for (const rawLine of rawLines) {
      const l = rawLine.trim();
      if (!l || l.startsWith('#') || l.startsWith('//')) continue;
      const parts = l.split(/[,;\-—–]+/).map(s => s.trim()).filter(Boolean);
      if (parts.length === 0) continue;
      const name = parts[0];
      const feePart = parts.length > 1 ? parts[1] : '€5.0M';
      const typePart = parts.length > 2 ? parts[2] : '';
      const extraPart = parts.length > 3 ? parts[3] : '';
      const fullLine = (typePart + ' ' + extraPart + ' ' + feePart).toLowerCase();
      const isMand = /сохранении|прописки|mandatory|выкуп|услови/i.test(fullLine);
      const isLoan = isMand || /аренда|loan/i.test(typePart) || /аренда|loan/i.test(feePart);
      const sellMatch = fullLine.match(/(?:sell[- ]?on|перепродаж\w*)[^\d]*(\d+)\s*%/i) || fullLine.match(/(\d+)\s*%\s*(?:sell[- ]?on|перепродаж\w*)/i);
      const sellOnPct = sellMatch ? Math.min(90, Math.max(0, Number(sellMatch[1]))) : 0;
      let cond = isMand ? 'Сохранение прописки в РПЛ' : undefined;
      const condMatch = l.match(/услови[^\s:]*:\s*([^,;]+)/i) || l.match(/при условии\s*([^,;]+)/i);
      if (condMatch) cond = condMatch[1].trim();
      itemsToProcess.push({
        name,
        fee: feePart,
        type: isMand ? 'loan_mandatory_rpl' : (isLoan ? 'loan' : 'transfer'),
        mandatoryBuyout: isMand,
        buyoutFee: isMand ? feePart : undefined,
        loanCondition: cond,
        sellOnPercent: sellOnPct
      });
    }
  } else if (playerName) {
    const isMand = String(transferType || '').includes('mandatory') || !!req.body.mandatoryBuyout;
    itemsToProcess.push({
      name: String(playerName).trim(),
      fee: String(fee || '€5.0M').trim(),
      type: isMand ? 'loan_mandatory_rpl' : (String(transferType || '').includes('loan') ? 'loan' : 'transfer'),
      mandatoryBuyout: isMand,
      buyoutFee: isMand ? String(req.body.buyoutFee || fee || '€8.0M').trim() : undefined,
      loanCondition: isMand ? String(req.body.loanCondition || req.body.buyoutCondition || 'Сохранение прописки в РПЛ').trim() : undefined,
      sellOnPercent: Math.min(90, Math.max(0, Number(req.body.sellOnPercent) || 0))
    });
  }

  if (!itemsToProcess.length) {
    return fail(res, 'Укажите ФИО игрока и цену (или введите список игроков)');
  }

  const createdRequests: any[] = [];
  for (const item of itemsToProcess) {
    const enriched = await enrichEuropeanPlayer(item.name, item.fee, item.type);
    const reqObj: any = {
      id: 'trq_' + uid(),
      clubId: req.me.teamId,
      clubName: buyerTeam.name,
      clubLogo: teamLogo(req.me.teamId),
      playerName: item.name,
      pos: enriched.pos,
      age: enriched.age,
      nationality: enriched.nationality,
      fromClub: enriched.fromClub,
      marketValue: enriched.marketValue,
      ovr: enriched.ovr,
      style: enriched.style,
      fee: item.fee || enriched.marketValue || 'По согласованию',
      feeAmount: parseFeeAmount(item.fee || enriched.marketValue),
      transferType: item.type,
      mandatoryBuyoutOnRplRetention: !!item.mandatoryBuyout,
      mandatoryBuyout: !!item.mandatoryBuyout,
      buyoutFee: item.buyoutFee || null,
      loanCondition: item.loanCondition || (item.mandatoryBuyout ? 'Сохранение прописки в РПЛ' : null),
      sellOnPercent: Number(item.sellOnPercent) || 0,
      status: 'pending',
      aiVerdict: null as any,
      createdAt: new Date().toISOString()
    };
    db.transferRequests.unshift(reqObj);
    createdRequests.push(reqObj);
  }

  save();
  res.json({
    ok: 1,
    count: createdRequests.length,
    requests: createdRequests,
    message: createdRequests.length === 1
      ? `Заявка по игроку ${createdRequests[0].playerName} из Европы отправлена на рассмотрение администратору.`
      : `Отправлено ${createdRequests.length} заявок на трансферы из Европы администратору.`
  });
});

